// DOP-C02 DevOps Engineer Professional - 168 questions. Generated by tools/build_banks.py, do not edit by hand.
window.QUESTION_BANKS = window.QUESTION_BANKS || {};
window.QUESTION_BANKS["DOP-C02"] = [
{"id": "aa:dop-0001", "sources": ["aa:dop-0001"], "q": "On every merge to the main branch, a microservice must run unit tests, build a container image, push it to Amazon ECR, deploy to a staging Amazon ECS service, and then deploy to production only after a release manager approves. The team wants the least custom orchestration code and a durable, auditable record of every release. Which approach best meets these requirements?", "options": [{"k": "A", "t": "Use AWS CodePipeline with a CodeBuild stage for tests and image build/push, an ECS deploy action to staging, a manual approval action, then an ECS deploy action to production"}, {"k": "B", "t": "Trigger an AWS Lambda function on each commit that runs tests and shells out to the AWS CLI to build, push, and deploy at every stage"}, {"k": "C", "t": "Schedule an AWS CodeBuild project every five minutes to detect new commits, then build and deploy straight to production"}, {"k": "D", "t": "Run a self-managed Jenkins server on Amazon EC2 that performs all stages and writes its own approval and audit log"}], "answer": ["A"], "multi": false, "explanation": "CodePipeline natively orchestrates source -> build/test -> staging deploy -> manual approval -> production deploy and records each execution (including the approver) for auditing, with no orchestration code. A Lambda+CLI driver is custom orchestration to maintain; the scheduled build polls and skips staging/approval; self-managed Jenkins adds undifferentiated server management."},
{"id": "aa:dop-0002", "sources": ["aa:dop-0002"], "q": "A production AWS Lambda function fronted by Amazon API Gateway serves live traffic. The team must release a new version so that 10% of invocations go to it for 5 minutes before full promotion, with automatic rollback if the function error rate rises, no change required of API clients, and the least custom code. Which approach is MOST operationally efficient?", "options": [{"k": "A", "t": "Publish a new function version behind a Lambda alias and use AWS CodeDeploy canary traffic shifting (Canary10Percent5Minutes) with a CloudWatch alarm configured for automatic rollback"}, {"k": "B", "t": "Keep two function versions and add a wrapper Lambda that forwards roughly 10% of invocations to the new version, reverting by editing the wrapper when errors appear"}, {"k": "C", "t": "Create a second API Gateway stage that integrates the new version and use a Route 53 weighted record to send 10% of traffic to it"}, {"k": "D", "t": "Deploy the new code with CodeDeployDefault.LambdaAllAtOnce and watch the error metrics afterward"}], "answer": ["A"], "multi": false, "explanation": "A Lambda alias with CodeDeploy canary shifting moves a defined percentage for a set interval and rolls back automatically when an associated CloudWatch alarm fires, with no client change and minimal configuration. A wrapper function is custom routing code; a second stage plus Route 53 adds stage and DNS overhead; AllAtOnce provides no gradual shift or automatic rollback window."},
{"id": "aa:dop-0003", "sources": ["aa:dop-0003"], "q": "An Amazon ECS on AWS Fargate service behind an Application Load Balancer must be updated so that the new task set is validated through a separate test listener before any production traffic reaches it, production cutover is near-instant, and rollback to the previous task set takes seconds if validation fails. Which deployment configuration meets all of these requirements?", "options": [{"k": "A", "t": "A CodeDeploy blue/green deployment for ECS with two target groups and a test listener, using lifecycle hooks to validate the green task set before the production listener is shifted"}, {"k": "B", "t": "An ECS rolling update with minimumHealthyPercent 100 and maximumPercent 200, validating the tasks after they are replaced"}, {"k": "C", "t": "An in-place task definition update that relies on the ECS deployment circuit breaker to roll back on failed health checks"}, {"k": "D", "t": "Deploy the new task definition to a second ECS cluster and repoint the ALB target group manually after testing"}], "answer": ["A"], "multi": false, "explanation": "ECS blue/green via CodeDeploy supports a test listener and BeforeAllowTraffic/AfterAllowTraffic hooks to validate the green task set before the production listener is shifted, giving near-instant cutover and seconds-fast rollback by routing back to the original task set. Rolling updates and the circuit breaker replace tasks without a separately validated green environment; a second cluster with manual repointing is slower and error-prone."},
{"id": "aa:dop-0004", "sources": ["aa:dop-0004"], "q": "A CodeBuild project for a large service spends most of each 14-minute build re-downloading dependencies and rebuilding Docker layers that rarely change. The team wants to cut build time with no build infrastructure to operate and without committing dependencies or prebuilt images to the source repository. What should they do?", "options": [{"k": "A", "t": "Enable CodeBuild caching: a local cache for the dependency directory and Docker layer cache, or an Amazon S3 cache shared across builds"}, {"k": "B", "t": "Move builds to a fleet of self-managed Amazon EC2 build agents with pre-warmed dependency caches"}, {"k": "C", "t": "Commit the resolved dependencies and a prebuilt base image into the repository so they are not downloaded"}, {"k": "D", "t": "Batch merges and run the build once nightly to reduce how often dependencies are downloaded"}], "answer": ["A"], "multi": false, "explanation": "CodeBuild local caching (custom paths plus Docker layer cache) or S3 caching reuses dependencies and unchanged image layers across builds with no servers to manage and without bloating the repo. Self-managed agents add operational overhead, committing dependencies and images is explicitly excluded, and nightly batching does not reduce per-build time and delays feedback."},
{"id": "aa:dop-0005", "sources": ["aa:dop-0005"], "q": "A CodePipeline in a shared tooling account builds encrypted artifacts and must deploy them by creating CloudFormation stacks in a separate production account. The deployment currently fails when the production-account actions try to read the artifacts. Which TWO configurations are required for the cross-account deployment to succeed?", "options": [{"k": "A", "t": "Encrypt the artifact bucket with a customer-managed KMS key whose key policy grants usage to the production account, and reference that key in the pipeline"}, {"k": "B", "t": "Create an IAM role in the production account that trusts the tooling account, grant it artifact bucket and KMS decrypt access, and have the pipeline assume it to deploy"}, {"k": "C", "t": "Grant the pipeline service role only s3:GetObject on the artifact bucket, without any KMS permissions"}, {"k": "D", "t": "Replace the customer-managed key with the AWS managed aws/s3 key and share it by editing its key policy"}, {"k": "E", "t": "Establish a VPC peering connection between the accounts so the pipeline can reach CloudFormation"}], "answer": ["A", "B"], "multi": true, "explanation": "Cross-account artifacts must be encrypted with a customer-managed KMS key shared through its key policy (the default aws/s3 key policy cannot be edited to share it), and the pipeline must assume a role in the production account that can read the bucket and decrypt with that key. GetObject without kms:Decrypt fails on encrypted artifacts, and CloudFormation is reached over its public endpoint rather than VPC peering."},
{"id": "aa:dop-0006", "sources": ["aa:dop-0006"], "q": "A pipeline deploys to production automatically. A new compliance control requires that a designated release manager explicitly approve each production deployment, that the approver be notified when a release is waiting, and that who approved and when be auditable, all with no custom code. What should be added before the production stage?", "options": [{"k": "A", "t": "A CodePipeline manual approval action that publishes to an SNS topic for notification; the approver and timestamp are recorded in the pipeline execution history and CloudTrail"}, {"k": "B", "t": "An SNS topic that emails the release manager, who then manually starts a separate production pipeline from the console"}, {"k": "C", "t": "A Lambda invoke action that waits for and parses an approval reply email before continuing"}, {"k": "D", "t": "A CloudWatch alarm that holds the pipeline until an on-call engineer acknowledges it"}], "answer": ["A"], "multi": false, "explanation": "A manual approval action gates the pipeline, can notify through SNS, and records the approver and timestamp in the execution history and CloudTrail with no code. Email-then-manual-start is not a recorded in-pipeline approval, an email-parsing Lambda is custom code, and CloudWatch alarms do not gate pipeline stages."},
{"id": "aa:dop-0007", "sources": ["aa:dop-0007"], "q": "A CodeDeploy blue/green deployment to Amazon EC2 must run an automated integration test suite against the replacement (green) instances and abort the deployment so that no production traffic is ever shifted if the tests fail. In which AppSpec lifecycle event hook should the tests run, and what is the effect of a failure?", "options": [{"k": "A", "t": "BeforeAllowTraffic; a non-zero hook exit fails the deployment before the load balancer routes production traffic, triggering rollback"}, {"k": "B", "t": "AfterAllowTraffic; the tests run once the green instances are already serving production traffic"}, {"k": "C", "t": "ApplicationStop; the hook runs on the original (blue) instances as they are deregistered"}, {"k": "D", "t": "ValidateService on the blue instances before the green instances are provisioned"}], "answer": ["A"], "multi": false, "explanation": "BeforeAllowTraffic runs after the green instances are provisioned but before the load balancer routes production traffic; a non-zero exit fails the deployment and triggers rollback, so users never reach a bad build. AfterAllowTraffic is post-cutover, ApplicationStop runs on the outgoing instances, and ValidateService on blue is the wrong target and timing."},
{"id": "aa:dop-0008", "sources": ["aa:dop-0008"], "q": "A CodeDeploy EC2/on-premises deployment must automatically redeploy the last known good revision whenever a deployment fails OR a CloudWatch alarm for elevated 5xx errors enters ALARM during or shortly after the deployment, with the least configuration and no operator action. How should this be configured?", "options": [{"k": "A", "t": "Enable automatic rollback on deployment failure and on alarm in the deployment group, and associate the 5xx CloudWatch alarm"}, {"k": "B", "t": "Create an EventBridge rule on the alarm that invokes a Lambda function which calls CreateDeployment with the previous revision"}, {"k": "C", "t": "Run a scheduled canary-analysis Lambda that decides each interval whether to revert to the prior revision"}, {"k": "D", "t": "Rely on the Amazon ECS deployment circuit breaker to revert the application"}], "answer": ["A"], "multi": false, "explanation": "CodeDeploy deployment groups natively support automatic rollback on deployment failure and on associated CloudWatch alarms, redeploying the last successful revision with no custom code or operator action. An EventBridge+Lambda rollback is custom orchestration, a scheduled analysis adds latency, and the ECS circuit breaker does not apply to EC2/on-premises deployments."},
{"id": "aa:dop-0009", "sources": ["aa:dop-0009"], "q": "A security team requires that every pipeline execution perform static application security testing (SAST) and software composition analysis (dependency scanning), stop before deploying if either finds a Critical issue, and centralize the findings in AWS Security Hub. Which TWO actions implement these requirements?", "options": [{"k": "A", "t": "Add CodeBuild stages that run the SAST and dependency-scanning tools and exit non-zero on Critical findings so the pipeline halts before deployment"}, {"k": "B", "t": "Have the build convert results to the AWS Security Finding Format and import them to Security Hub (for example, via BatchImportFindings)"}, {"k": "C", "t": "Use Amazon Inspector to perform SAST by scanning the source code repository"}, {"k": "D", "t": "Add a manual approval action and have a reviewer read the scan logs before each deployment"}, {"k": "E", "t": "Enable Amazon GuardDuty to block the pipeline when it detects code vulnerabilities"}], "answer": ["A", "B"], "multi": true, "explanation": "SAST and dependency scanning run as CodeBuild stages whose non-zero exit halts the pipeline before deployment, and findings sent to Security Hub in ASFF centralize them. Inspector scans EC2/ECR/Lambda rather than performing source SAST, a manual approval is not automated gating, and GuardDuty detects account threats, not code vulnerabilities."},
{"id": "aa:dop-0010", "sources": ["aa:dop-0010"], "q": "A CodePipeline sourced from AWS CodeCommit must start within seconds of a push to the release branch, must avoid the cost and latency of periodic polling, and must not start for pushes to any other branch. How should the team configure the trigger?", "options": [{"k": "A", "t": "Disable periodic checks and create an EventBridge rule that matches CodeCommit referenceUpdated events for the release branch and starts the pipeline"}, {"k": "B", "t": "Keep periodic polling on the source action but reduce the polling interval to its minimum"}, {"k": "C", "t": "Create an EventBridge scheduled rule that calls StartPipelineExecution every minute"}, {"k": "D", "t": "Add a CodeBuild webhook on the repository to start the pipeline on each push"}], "answer": ["A"], "multi": false, "explanation": "An EventBridge rule on CodeCommit repository state-change events starts the pipeline within seconds and can filter on the branch reference, eliminating polling cost/latency and ignoring other branches. Minimum-interval polling and a per-minute scheduled rule still poll and add latency, and CodeBuild webhooks apply to third-party Git sources, not CodeCommit-triggered pipeline starts."},
{"id": "aa:dop-0011", "sources": ["aa:dop-0011"], "q": "A production CloudFormation stack may have been changed outside of CloudFormation. An engineer runs drift detection, but a security group ingress rule that was edited manually is reported as IN_SYNC instead of drifted. What is the most likely cause, and how can the engineer get accurate drift results?", "options": [{"k": "A", "t": "Drift detection only compares properties explicitly declared in the template; the edited property was left at its default and not declared, so declare it (even at its default value) and re-run drift detection"}, {"k": "B", "t": "Drift detection is eventually consistent, so waiting about 24 hours will eventually report the manual change"}, {"k": "C", "t": "Drift detection cannot evaluate security groups, so AWS Config must be used exclusively for this resource type"}, {"k": "D", "t": "The stack must be deleted and recreated before drift detection can compare any properties"}], "answer": ["A"], "multi": false, "explanation": "Drift detection compares actual values only against properties explicitly set in the template or via parameters; a property left at its service default is not tracked, so a manual change to it is reported as in sync. Declaring the property makes drift detection evaluate it. Drift is not delayed by a consistency window, it supports security groups, and it does not require recreating the stack."},
{"id": "aa:dop-0012", "sources": ["aa:dop-0012"], "q": "A platform team must deploy a common baseline (IAM roles, a VPC, and centralized logging) to all 60 accounts in an AWS Organization and to every account that joins later, in two Regions, and update them centrally with minimal ongoing effort. Which approach meets this with the least operational overhead?", "options": [{"k": "A", "t": "A service-managed CloudFormation StackSet targeting the organization or specific OUs, with automatic deployment enabled, deploying to both Regions"}, {"k": "B", "t": "A self-managed StackSet for which the team creates execution roles in each account and adds the account IDs to the StackSet manually"}, {"k": "C", "t": "A single CloudFormation stack in the management account that exports values for member accounts to import"}, {"k": "D", "t": "A CodePipeline that runs the AWS CLI to deploy the template against each account ID listed in a configuration file"}], "answer": ["A"], "multi": false, "explanation": "A service-managed StackSet integrates with Organizations, deploys across many accounts and Regions in one operation, and with automatic deployment enabled adds new accounts in target OUs automatically, which is the least ongoing effort. Self-managed StackSets and a per-account pipeline require maintaining account lists and roles, and a single stack with cross-stack exports does not span accounts."},
{"id": "aa:dop-0013", "sources": ["aa:dop-0013"], "q": "A team operates service-managed CloudFormation StackSets across an AWS Organization. Which TWO statements accurately describe how they behave?", "options": [{"k": "A", "t": "With automatic deployment enabled, stack instances are created in accounts as they are added to a target OU and removed when accounts leave the OU"}, {"k": "B", "t": "A single StackSet operation can create or update stack instances across multiple accounts and Regions, with configurable maximum concurrency and failure tolerance"}, {"k": "C", "t": "Service-managed StackSets require you to manually create the StackSet execution role in every target account before deployment"}, {"k": "D", "t": "Stack instances in different Regions of the same account share one underlying physical stack"}, {"k": "E", "t": "StackSets can target only the organization management account, not member accounts"}], "answer": ["A", "B"], "multi": true, "explanation": "Service-managed StackSets auto-deploy to accounts joining target OUs and remove instances when accounts leave, and one operation spans many accounts and Regions with concurrency and failure-tolerance controls. Service-managed mode uses service-linked roles rather than manually created execution roles, each account/Region pair is a separate stack instance, and member accounts can be targeted."},
{"id": "aa:dop-0014", "sources": ["aa:dop-0014"], "q": "An Auto Scaling group is created by CloudFormation. The stack must not report CREATE_COMPLETE for the group until a required number of instances finish bootstrapping their application, and the stack must fail if bootstrapping does not succeed within a time limit. Which configuration accomplishes this?", "options": [{"k": "A", "t": "Add a CreationPolicy with ResourceSignal (Count and Timeout) to the Auto Scaling group, and have instance user data call cfn-signal with the bootstrap exit code"}, {"k": "B", "t": "Add an UpdatePolicy with AutoScalingRollingUpdate, which blocks creation until the instances signal success"}, {"k": "C", "t": "Add a DependsOn from the Auto Scaling group to its launch template so creation waits for bootstrapping"}, {"k": "D", "t": "Add a DeletionPolicy of Snapshot so the group reports completion only after instances are healthy"}], "answer": ["A"], "multi": false, "explanation": "A CreationPolicy with ResourceSignal makes CloudFormation wait for the specified number of success signals within the timeout; instance user data calls cfn-signal with the bootstrap result, so the stack fails if the signals are not received in time. UpdatePolicy governs updates rather than the creation gate, DependsOn only orders resource creation, and DeletionPolicy controls deletion behavior."},
{"id": "aa:dop-0015", "sources": ["aa:dop-0015"], "q": "A fleet of EC2 instances must continuously enforce a desired configuration (required agents installed, specific services running, approved settings), automatically reapply that configuration on a schedule to correct drift, and report which instances are non-compliant, without building custom tooling. Which Systems Manager capability fits best?", "options": [{"k": "A", "t": "State Manager associations that apply a configuration document on a schedule and report association compliance"}, {"k": "B", "t": "Run Command, executed once by an operator whenever configuration drift is suspected"}, {"k": "C", "t": "Session Manager sessions used to connect to each instance and correct settings manually"}, {"k": "D", "t": "Inventory, which collects installed-software and configuration metadata for reporting"}], "answer": ["A"], "multi": false, "explanation": "State Manager associations apply and re-apply a configuration document on a schedule, enforcing the desired state and reporting compliance. Run Command is a one-time action, Session Manager is interactive access, and Inventory only collects metadata without enforcing configuration."},
{"id": "aa:dop-0016", "sources": ["aa:dop-0016"], "q": "Hundreds of EC2 instances across dev, test, and prod must be patched on a monthly schedule within approved maintenance windows, using a different approved-patch baseline per environment, and the company must produce a report of which instances are patched versus missing patches. Which approach is the most operationally efficient?", "options": [{"k": "A", "t": "Use Systems Manager Patch Manager with per-environment patch baselines, patch groups defined by tags, maintenance windows, and patch compliance reporting"}, {"k": "B", "t": "Use State Manager to install all available updates immediately on every instance, with no baselines or maintenance windows"}, {"k": "C", "t": "Bake a fully patched AMI each month, replace all instances with an Auto Scaling instance refresh, and track patch status in a spreadsheet"}, {"k": "D", "t": "Run an on-demand Run Command package update across all instances and email the command output to the operations team"}], "answer": ["A"], "multi": false, "explanation": "Patch Manager applies per-group patch baselines during maintenance windows and reports patch compliance centrally, satisfying scheduling, per-environment baselines, and reporting with the least effort. State Manager with no baselines ignores environment-specific control, an AMI rebuild with spreadsheet tracking lacks native patch-compliance reporting, and on-demand Run Command lacks scheduling, baselines, and a compliance store."},
{"id": "aa:dop-0017", "sources": ["aa:dop-0017"], "q": "Before applying an update to a production CloudFormation stack that includes an RDS database, a team must know in advance which resources will be modified, which will require replacement (risking data loss), and which will be deleted, and must let a reviewer approve that plan before anything changes. What should they use?", "options": [{"k": "A", "t": "Create a CloudFormation change set, review the proposed actions including any Replacement: True resources, and execute it only after approval"}, {"k": "B", "t": "Apply a stack policy that denies all updates, then run the update to see what is blocked"}, {"k": "C", "t": "Enable termination protection on the stack and then run the update"}, {"k": "D", "t": "Run drift detection on the stack before performing the update"}], "answer": ["A"], "multi": false, "explanation": "A change set shows the proposed add/modify/replace/delete actions and flags resource replacements before execution, so a reviewer can approve the plan and avoid surprise data-loss replacements. Stack policies restrict updates rather than preview them, termination protection only blocks stack deletion, and drift detection compares the current state to the template rather than previewing a pending update."},
{"id": "aa:dop-0018", "sources": ["aa:dop-0018"], "q": "An application on Amazon ECS needs database credentials that are rotated automatically every 30 days using the database engine native rotation, encrypted at rest, retrievable by the task at runtime, and also readable by a second AWS account that runs a reporting job. Which solution meets all requirements with the least custom code?", "options": [{"k": "A", "t": "Store the credentials in AWS Secrets Manager, enable managed rotation for the database, encrypt with a customer-managed KMS key, and grant the second account access through the secret resource policy and the KMS key policy"}, {"k": "B", "t": "Store the credentials in Systems Manager Parameter Store as a SecureString and write a scheduled Lambda function to rotate them and to share them across accounts"}, {"k": "C", "t": "Store the credentials in a DynamoDB table encrypted with KMS and rotate them with a custom application job"}, {"k": "D", "t": "Place the credentials in the ECS task definition as environment variables and rotate them by redeploying the task each month"}], "answer": ["A"], "multi": false, "explanation": "Secrets Manager provides managed database rotation, KMS encryption, runtime retrieval, and cross-account access through the secret resource policy plus the KMS key policy, with no custom code. Parameter Store SecureString has no native rotation, a DynamoDB table with a custom job is custom code, and environment-variable credentials are insecure and manually rotated."},
{"id": "aa:dop-0019", "sources": ["aa:dop-0019"], "q": "A stateless web tier on EC2 must stay available during the loss of an entire Availability Zone, automatically replace instances that fail health checks, and retain enough capacity to serve normal load even while one AZ is unavailable. Which configuration meets all of these requirements?", "options": [{"k": "A", "t": "An Auto Scaling group spread across at least three Availability Zones behind an Application Load Balancer with ELB health checks, sized so the remaining AZs absorb the load"}, {"k": "B", "t": "An Auto Scaling group across two Availability Zones running at exactly the minimum capacity needed for normal load"}, {"k": "C", "t": "One EC2 instance in each of three Availability Zones, each with an Elastic IP and a Route 53 failover record"}, {"k": "D", "t": "An Auto Scaling group in a single Availability Zone using a larger instance type and detailed monitoring"}], "answer": ["A"], "multi": false, "explanation": "An ASG across three or more AZs with an ALB and ELB health checks replaces unhealthy instances automatically and, when sized so the surviving AZs absorb the load, keeps serving during a full AZ outage. Two AZs at minimum capacity loses half the fleet on AZ failure, single-instance-per-AZ designs lack automatic replacement and scaling, and a single AZ is not AZ-fault-tolerant."},
{"id": "aa:dop-0020", "sources": ["aa:dop-0020"], "q": "An Amazon Aurora MySQL workload must support disaster recovery in a second Region with an RPO of about one second, managed cross-Region failover in roughly a minute, and low-latency reads served from the second Region during normal operation. Which feature meets all of these requirements?", "options": [{"k": "A", "t": "Aurora Global Database, which replicates to a secondary Region with typically sub-second lag, supports managed cross-Region failover, and serves reads from the secondary Region"}, {"k": "B", "t": "An Aurora cross-Region read replica rebuilt each day from a snapshot copied to the second Region"}, {"k": "C", "t": "A single-Region Aurora Multi-AZ cluster with automated backups enabled"}, {"k": "D", "t": "AWS Backup copying Aurora cluster snapshots to the second Region every 6 hours"}], "answer": ["A"], "multi": false, "explanation": "Aurora Global Database replicates storage to a secondary Region with typically sub-second lag, supports fast managed cross-Region failover, and lets the secondary Region serve reads during normal operation. Daily snapshot rebuilds and 6-hourly copies give an RPO of hours, and a single-Region Multi-AZ cluster is not cross-Region disaster recovery."},
{"id": "aa:dop-0021", "sources": ["aa:dop-0021"], "q": "A company runs the same application in two Regions, each behind its own Application Load Balancer. During normal operation all users must be served by the primary Region, but if the primary endpoint becomes unhealthy, DNS must automatically direct users to the secondary Region. Which Route 53 configuration meets this active-passive requirement?", "options": [{"k": "A", "t": "Failover routing with a health check on the primary ALB: the primary record is returned while healthy and the secondary record is returned when the primary health check fails"}, {"k": "B", "t": "Weighted routing with 100 percent weight on the primary and 0 percent on the secondary, changed manually during an outage"}, {"k": "C", "t": "Latency-based routing between the two Regions with no health checks configured"}, {"k": "D", "t": "Simple routing with both ALB endpoints listed in a single record set"}], "answer": ["A"], "multi": false, "explanation": "Failover routing with a health check on the primary serves the primary while it is healthy and automatically returns the secondary when the primary health check fails, achieving active-passive DNS failover. Weighted routing requires manual changes, latency routing does not enforce primary-only behavior or fail over on health, and simple routing has no health awareness."},
{"id": "aa:dop-0022", "sources": ["aa:dop-0022"], "q": "A business application must recover in a second Region with an RTO of about 10 minutes and an RPO of seconds, while avoiding the cost of a full-scale duplicate environment during normal operation. A scaled-down but fully functional copy of the workload is acceptable. Which disaster recovery strategy best fits these constraints?", "options": [{"k": "A", "t": "Warm standby: a continuously running, reduced-capacity copy of the full stack with data replicated, scaled up on failover"}, {"k": "B", "t": "Backup and restore: rebuild infrastructure and restore data from backups after a disaster is declared"}, {"k": "C", "t": "Multi-site active/active: full-scale capacity running in both Regions at all times"}, {"k": "D", "t": "Pilot light: replicate only the database while core application servers stay switched off until needed"}], "answer": ["A"], "multi": false, "explanation": "Warm standby keeps a smaller but fully functional copy of the workload always running with data replicated, scaling it up on failover to meet a low RTO without paying for full duplicate capacity. Backup and restore has a much higher RTO, active/active costs more than required, and pilot light keeps most compute off and typically yields a longer RTO than warm standby."},
{"id": "aa:dop-0023", "sources": ["aa:dop-0023"], "q": "EC2 instances in an Auto Scaling group process long-running jobs. When the group scales in, an instance chosen for termination must finish its in-flight job and upload its logs before it is terminated, but scale-in must not be blocked indefinitely if that cleanup hangs. Which mechanism provides this behavior?", "options": [{"k": "A", "t": "An EC2_INSTANCE_TERMINATING lifecycle hook that holds the instance in Terminating:Wait with a heartbeat timeout, completing the lifecycle action when cleanup finishes"}, {"k": "B", "t": "Instance scale-in protection enabled permanently on every instance in the group"}, {"k": "C", "t": "A target tracking scaling policy configured with a long cooldown period"}, {"k": "D", "t": "A load balancer deregistration delay (connection draining) on the target group only"}], "answer": ["A"], "multi": false, "explanation": "A terminating lifecycle hook places the instance in Terminating:Wait so cleanup can run, and the heartbeat timeout bounds the wait so a hung cleanup does not block scale-in forever. Permanent scale-in protection prevents scale-in entirely, scaling policies and cooldowns do not gate termination cleanup, and deregistration delay only drains load balancer connections, not the job completion and log upload."},
{"id": "aa:dop-0024", "sources": ["aa:dop-0024"], "q": "An Amazon ECS service has variable load. The number of tasks must scale out when average CPU utilization across the service exceeds a target and scale back in when it falls, automatically, while a capacity provider supplies the underlying EC2 capacity. Which configuration scales the task count correctly?", "options": [{"k": "A", "t": "Configure Application Auto Scaling with a target tracking policy on the ECS service average CPU utilization metric"}, {"k": "B", "t": "Configure an EC2 Auto Scaling group target tracking policy and keep the ECS service desired count fixed"}, {"k": "C", "t": "Use a scheduled scaling action to change the service desired count at fixed times of day"}, {"k": "D", "t": "Invoke a Lambda function on a timer that reads the latest CPU sample and sets the desired count"}], "answer": ["A"], "multi": false, "explanation": "Application Auto Scaling target tracking on the ECS service CPU metric adjusts the service desired task count to hold the target. Scaling the EC2 Auto Scaling group changes cluster capacity but not the task count, scheduled scaling is not load-responsive, and a timer-driven Lambda is custom and coarse."},
{"id": "aa:dop-0025", "sources": ["aa:dop-0025"], "q": "A compliance team must centrally back up Amazon EBS volumes and Amazon RDS databases across many accounts in an Organization, copy each backup to a second Region for DR, enforce retention, and prevent any backup from being deleted before retention expires even by an administrator. Which TWO actions meet these requirements?", "options": [{"k": "A", "t": "Use AWS Backup with a backup plan that includes a cross-Region copy action and retention rules, managed centrally with AWS Backup policies in the Organization"}, {"k": "B", "t": "Apply AWS Backup Vault Lock in compliance mode on the destination vault so recovery points cannot be deleted before retention expires"}, {"k": "C", "t": "Rely on Amazon EBS and Amazon RDS replicating to a second Region automatically by default"}, {"k": "D", "t": "Grant administrators a vault lock bypass so they can remove backups during incident cleanup"}, {"k": "E", "t": "Store the backups only in the source Region to minimize cost"}], "answer": ["A", "B"], "multi": true, "explanation": "AWS Backup centralizes backups across accounts, supports cross-Region copy actions and retention in the backup plan, and Vault Lock in compliance mode makes recovery points immutable until retention expires, even for administrators and the root user. EBS and RDS are not cross-Region replicated by default, a bypass defeats immutability, and source-only storage provides no DR copy."},
{"id": "aa:dop-0026", "sources": ["aa:dop-0026"], "q": "A central monitoring team must view CloudWatch metrics, logs, and X-Ray traces from dozens of member accounts in one account, onboard new accounts automatically, and avoid copying telemetry on a schedule. Which approach meets this with the least ongoing administration?", "options": [{"k": "A", "t": "Enable CloudWatch cross-account observability: create a sink in the monitoring account and Observability Access Manager links in source accounts, deployed across the Organization so new accounts link automatically"}, {"k": "B", "t": "Deploy a Lambda function in each account that periodically copies metrics and log events into the monitoring account"}, {"k": "C", "t": "Create a cross-account IAM role in every account and have engineers switch roles to view each account console separately"}, {"k": "D", "t": "Stream all logs to one central S3 bucket and rebuild metric and trace views from Amazon Athena queries"}], "answer": ["A"], "multi": false, "explanation": "CloudWatch cross-account observability (OAM) shares metrics, logs, and traces from source accounts to a monitoring account through a sink and links, and can be deployed organization-wide so new accounts onboard automatically. Per-account copy Lambdas, role-switching, and S3-plus-Athena are custom, manual, or lose the unified metric and trace view."},
{"id": "aa:dop-0027", "sources": ["aa:dop-0027"], "q": "An application writes structured JSON logs to CloudWatch Logs. The team must page on-call in near real time when more than 10 records with level ERROR appear within any 5-minute window, without provisioning servers or writing custom counting code. What is the most efficient approach?", "options": [{"k": "A", "t": "Create a metric filter on the log group that increments a metric when the ERROR pattern matches, then a CloudWatch alarm with a threshold greater than 10 over 5 minutes and an SNS action to the pager"}, {"k": "B", "t": "Create a subscription filter to a Lambda function that counts ERROR records and decides whether to page"}, {"k": "C", "t": "Run a CloudWatch Logs Insights query every 5 minutes from EventBridge and a Lambda function that pages when the count exceeds 10"}, {"k": "D", "t": "Enable AWS Config to evaluate the log group and alarm on the error count"}], "answer": ["A"], "multi": false, "explanation": "A metric filter converts matching log events into a CloudWatch metric, and an alarm on that metric with an SNS action pages in near real time with no servers or counting code. A subscription-filter Lambda and a scheduled Logs Insights query add code and latency, and AWS Config does not evaluate log contents."},
{"id": "aa:dop-0028", "sources": ["aa:dop-0028"], "q": "A request that traverses Amazon API Gateway, several AWS Lambda functions, and a downstream Amazon DynamoDB table shows intermittent high latency, and the team cannot tell which hop is slow. They need a per-segment latency view and to locate error and throttle hotspots across the whole path with minimal code changes. Which solution provides this?", "options": [{"k": "A", "t": "Instrument the path with AWS X-Ray (enable tracing on API Gateway and Lambda and use the X-Ray SDK or ADOT) and use the service map and trace analytics to find the slow segment"}, {"k": "B", "t": "Enable VPC Flow Logs and analyze them for latency between the components"}, {"k": "C", "t": "Build CloudWatch dashboards of each service average duration and visually correlate the spikes"}, {"k": "D", "t": "Turn on AWS Config to record configuration changes that occur during the slow periods"}], "answer": ["A"], "multi": false, "explanation": "X-Ray provides distributed tracing with a service map and per-segment latency, error, and throttle breakdowns across API Gateway, Lambda, and DynamoDB, pinpointing the slow hop with minimal instrumentation. Flow Logs show network metadata rather than application latency, dashboards lack per-request correlation, and Config records configuration changes, not latency."},
{"id": "aa:dop-0029", "sources": ["aa:dop-0029"], "q": "An Amazon EKS platform team needs per-pod and per-node CPU, memory, disk, and network metrics plus the ability to query container logs, all presented in CloudWatch, with the least operational effort and no self-managed monitoring stack. Which should they enable?", "options": [{"k": "A", "t": "Amazon CloudWatch Container Insights with the CloudWatch agent and Fluent Bit for EKS"}, {"k": "B", "t": "A self-managed Prometheus and Grafana stack running on the cluster"}, {"k": "C", "t": "The default EKS control plane metrics, which already include per-pod memory and disk usage"}, {"k": "D", "t": "AWS Config aggregators to collect the container metrics centrally"}], "answer": ["A"], "multi": false, "explanation": "Container Insights collects per-pod and per-node metrics and integrates with CloudWatch Logs for EKS with minimal setup and no self-managed stack. A self-managed Prometheus and Grafana deployment adds operational effort, default EKS metrics do not include per-pod memory and disk, and AWS Config does not collect metrics."},
{"id": "aa:dop-0030", "sources": ["aa:dop-0030"], "q": "A security team must be alerted in near real time whenever any principal calls a specific sensitive API (for example, disabling a security control) in any account in the Organization, and must trigger an automated containment action. Which design meets this with the least custom infrastructure?", "options": [{"k": "A", "t": "Create an organization CloudTrail and, in a delegated security account, an EventBridge rule that matches the sensitive API event pattern and targets SNS for notification and an SSM Automation or Lambda action for containment"}, {"k": "B", "t": "Deliver CloudTrail logs to S3 in each account and run a nightly Amazon Athena query to find the API calls"}, {"k": "C", "t": "Enable Amazon GuardDuty and wait for it to raise a finding for the specific API call"}, {"k": "D", "t": "Create a CloudWatch dashboard widget that charts the count of the API call over time"}], "answer": ["A"], "multi": false, "explanation": "CloudTrail management events reach EventBridge, so an organization trail plus a rule matching the specific event pattern can notify through SNS and invoke automated containment immediately. Nightly Athena queries are not near real time, GuardDuty does not alert on arbitrary specific API calls, and a dashboard provides no alerting or automation."},
{"id": "aa:dop-0031", "sources": ["aa:dop-0031"], "q": "During an incident, a single root cause sets off many individual CloudWatch alarms and pages on-call repeatedly. The team wants to page only once when a meaningful combination is true (for example, high error rate AND elevated latency), while keeping the individual alarms available for dashboards. Which feature achieves this?", "options": [{"k": "A", "t": "A CloudWatch composite alarm whose rule combines the child alarm states with AND/OR logic and sends the notification, leaving the child alarms in place but not paging"}, {"k": "B", "t": "Delete all but the single most important alarm so only one can page"}, {"k": "C", "t": "Increase every alarm evaluation period to one day to reduce how often they page"}, {"k": "D", "t": "Combine all the alarms into one metric math expression alarm"}], "answer": ["A"], "multi": false, "explanation": "Composite alarms combine multiple child alarm states with logical rules and send a single notification when the combination is met, while the child alarms remain for visibility without paging. Deleting alarms loses coverage, lengthening periods hides real issues, and metric math cannot express arbitrary combinations of existing alarm states."},
{"id": "aa:dop-0032", "sources": ["aa:dop-0032"], "q": "Application logs in CloudWatch Logs must be kept for 7 years for audit, but only the last 30 days are queried frequently and storage cost must be minimized. The archived logs must remain retrievable for audits. What is the most cost-effective design?", "options": [{"k": "A", "t": "Set 30-day retention on the log group and continuously deliver logs to Amazon S3 (for example, a subscription filter to Kinesis Data Firehose) with S3 Lifecycle transitions to Glacier storage classes for the 7-year archive"}, {"k": "B", "t": "Set the CloudWatch Logs log group retention to 7 years and query it directly"}, {"k": "C", "t": "Disable the log group after 30 days and recreate it only when an audit needs the data"}, {"k": "D", "t": "Export the logs once to S3 Standard and keep them there for 7 years with no lifecycle tiering"}], "answer": ["A"], "multi": false, "explanation": "Short CloudWatch retention for hot queries plus continuous delivery to S3 with lifecycle tiering to Glacier classes meets the 7-year retrievable archive at the lowest cost. Seven-year CloudWatch retention is expensive, disabling the log group loses the data and fails the audit, and keeping everything in S3 Standard costs more than tiering to Glacier."},
{"id": "aa:dop-0033", "sources": ["aa:dop-0033"], "q": "An application publishes a custom CloudWatch metric. When the metric breaches its threshold, on-call must be paged within one minute AND an automated runbook must attempt remediation, with no servers to operate. Which TWO actions together accomplish this?", "options": [{"k": "A", "t": "Create a CloudWatch alarm on the metric with a 1-minute period and an SNS action that notifies the on-call paging integration"}, {"k": "B", "t": "Add an EventBridge rule on the alarm state change (or an alarm action) that starts an SSM Automation runbook to perform the remediation"}, {"k": "C", "t": "Enable AWS Config with a rule that evaluates the custom metric and remediates on breach"}, {"k": "D", "t": "Enable Amazon GuardDuty so it detects the metric threshold breach and pages the team"}, {"k": "E", "t": "Schedule a Lambda function once per day to read the metric and page if it is breached"}], "answer": ["A", "B"], "multi": true, "explanation": "A 1-minute alarm with an SNS action pages on-call quickly, and an EventBridge rule or alarm action that starts an SSM Automation runbook performs serverless auto-remediation. AWS Config and GuardDuty do not watch custom metrics, and a daily Lambda is far too slow to meet a one-minute requirement."},
{"id": "aa:dop-0034", "sources": ["aa:dop-0034"], "q": "Whenever a security group in any account in the Organization is modified to allow unrestricted inbound SSH (0.0.0.0/0 to port 22), the change must be reverted automatically within minutes, with no human action and managed centrally. Which approach is best?", "options": [{"k": "A", "t": "Deploy the restricted-ssh AWS Config managed rule organization-wide via a conformance pack, with an automatic remediation action that runs an SSM Automation document to remove the offending rule"}, {"k": "B", "t": "Create an EventBridge rule on the security group change that emails the security team so an engineer can revert it manually"}, {"k": "C", "t": "Attach an SCP that denies ec2:AuthorizeSecurityGroupIngress entirely in every account"}, {"k": "D", "t": "Produce a weekly AWS Config compliance report that an engineer reviews and acts on"}], "answer": ["A"], "multi": false, "explanation": "The restricted-ssh Config rule detects the noncompliant group and an associated SSM Automation remediation reverts it automatically; a conformance pack applies it organization-wide. Emailing is manual, a blanket SCP deny is over-broad (it blocks all ingress changes and does not remediate existing rules), and a weekly review is not within minutes."},
{"id": "aa:dop-0035", "sources": ["aa:dop-0035"], "q": "A single legacy EC2 instance that cannot be horizontally scaled must, on an underlying hardware (system status check) failure, be automatically moved to healthy hardware while keeping the same instance ID, private and Elastic IP addresses, and instance metadata, with no change required of clients. Which configuration meets this?", "options": [{"k": "A", "t": "A CloudWatch alarm on StatusCheckFailed_System with the EC2 recover action, or rely on simplified automatic recovery, which migrates the instance to new hardware preserving its ID, IPs, and metadata"}, {"k": "B", "t": "Place the instance in an Auto Scaling group with minimum and maximum size of 1 so a failed instance is replaced"}, {"k": "C", "t": "A CloudWatch alarm with a reboot action on the StatusCheckFailed_Instance metric"}, {"k": "D", "t": "An EventBridge rule on the AWS Health event that stops and then starts the instance"}], "answer": ["A"], "multi": false, "explanation": "The recover action (or simplified automatic recovery) responds to system status check failures by migrating the instance to new hardware while preserving instance ID, IPs, and metadata. An Auto Scaling group replaces the instance with a new identity, reboot addresses instance-level (OS) checks on the same hardware, and a stop/start workflow is custom and can change addressing."},
{"id": "aa:dop-0036", "sources": ["aa:dop-0036"], "q": "Objects uploaded to a specific prefix of an S3 bucket must immediately trigger a processing Lambda function, and the same events must also be delivered to a second consumer for an independent audit pipeline, with the least custom code and without coupling the two consumers. Which approach is best?", "options": [{"k": "A", "t": "Enable Amazon EventBridge notifications on the bucket and create rules matching the prefix that target the processing Lambda function and the audit consumer independently"}, {"k": "B", "t": "Configure a single S3 event notification to the processing Lambda function and have that function also invoke the audit pipeline"}, {"k": "C", "t": "Have the processing Lambda function poll the bucket every minute and forward each new object to both consumers"}, {"k": "D", "t": "Enable S3 server access logging and parse the logs hourly to drive both the processing and audit consumers"}], "answer": ["A"], "multi": false, "explanation": "Routing S3 events to EventBridge lets multiple rules fan the same object-created events out to several targets immediately and independently, with minimal code. A direct notification to one function couples the consumers, polling adds latency and cost, and access logs are not an immediate event source."},
{"id": "aa:dop-0037", "sources": ["aa:dop-0037"], "q": "An operations team wants operational issues raised by CloudWatch alarms and selected EventBridge events to become tracked, deduplicated work items that include the related resources and suggested runbooks, in order to reduce mean time to resolution. Which service provides this?", "options": [{"k": "A", "t": "AWS Systems Manager OpsCenter, which aggregates OpsItems from alarms and EventBridge with related resources and runbooks"}, {"k": "B", "t": "Amazon SNS topics that email the team for each alarm and event"}, {"k": "C", "t": "An AWS Config aggregator that centralizes configuration and compliance data"}, {"k": "D", "t": "A CloudWatch dashboard that visualizes the alarms and events"}], "answer": ["A"], "multi": false, "explanation": "OpsCenter centralizes operational issues as OpsItems created from alarms and EventBridge, deduplicates them, and attaches related resources and runbooks to reduce MTTR. SNS only sends notifications, a Config aggregator centralizes compliance data, and a dashboard visualizes data rather than tracking work items."},
{"id": "aa:dop-0038", "sources": ["aa:dop-0038"], "q": "An EventBridge rule targets a Lambda function. Occasionally EventBridge cannot deliver an event to the Lambda service even after exhausting its retry policy, and those events are currently lost. The team must retain undeliverable events for later inspection and reprocessing with the least custom code. What should they configure?", "options": [{"k": "A", "t": "Configure an Amazon SQS dead-letter queue on the EventBridge target to capture events that fail delivery after the retry policy is exhausted"}, {"k": "B", "t": "Configure a Lambda asynchronous on-failure destination, expecting it to capture the EventBridge delivery failures"}, {"k": "C", "t": "Increase the rule retry attempts to the maximum and assume events can no longer be lost"}, {"k": "D", "t": "Add a try/catch in the function that writes failed events to Amazon S3"}], "answer": ["A"], "multi": false, "explanation": "An SQS dead-letter queue on the EventBridge target captures events EventBridge cannot deliver after its retry policy, with no custom code. A Lambda on-failure destination only applies to events Lambda has already accepted but failed to process, raising retries still exhausts eventually, and in-function error handling cannot capture events that never reached the function."},
{"id": "aa:dop-0039", "sources": ["aa:dop-0039"], "q": "An application connects continuously to Amazon RDS and must have its database credentials rotated automatically on a schedule with no disruption to active connections during rotation, encrypted at rest, and managed without writing custom rotation code. Which approach best meets these requirements?", "options": [{"k": "A", "t": "Store the credentials in AWS Secrets Manager and enable rotation using the alternating-users strategy with the AWS-provided rotation function"}, {"k": "B", "t": "Store the credentials in AWS Secrets Manager and enable single-user rotation, accepting brief authentication failures while the password changes"}, {"k": "C", "t": "Store the credentials in Systems Manager Parameter Store as a SecureString and write a scheduled Lambda function to rotate them"}, {"k": "D", "t": "Store the credentials in AWS Secrets Manager but rotate them manually from the console each month"}], "answer": ["A"], "multi": false, "explanation": "Secrets Manager rotation with the alternating-users strategy provisions and alternates between two database users so active connections are not disrupted, using the AWS-provided rotation function with no custom code. Single-user rotation can briefly disrupt connections, Parameter Store has no native rotation, and manual rotation is not automatic."},
{"id": "aa:dop-0040", "sources": ["aa:dop-0040"], "q": "A security team must guarantee that no member account in an AWS Organization can create unencrypted Amazon EBS volumes, regardless of that account’s own IAM policies, with the simplest enforcement that account administrators cannot bypass. Which TWO statements correctly describe how to achieve this?", "options": [{"k": "A", "t": "Attach a Service Control Policy that denies ec2:CreateVolume when ec2:Encrypted is false to the relevant OUs or accounts"}, {"k": "B", "t": "An explicit Deny in the SCP overrides any Allow in the account IAM policies, so account administrators cannot bypass it"}, {"k": "C", "t": "Enabling EBS encryption by default in each account setting, by itself, prevents any administrator from ever creating an unencrypted volume"}, {"k": "D", "t": "An AWS Config rule alone blocks the CreateVolume API call at request time"}, {"k": "E", "t": "A permissions boundary on each IAM role guarantees that no unencrypted volume can be created anywhere in the account"}], "answer": ["A", "B"], "multi": true, "explanation": "An SCP that denies ec2:CreateVolume when ec2:Encrypted is false enforces the guardrail across the Organization, and an explicit Deny overrides every account-level Allow so administrators cannot bypass it. EBS encryption by default is a changeable per-account setting, AWS Config detects rather than blocks, and a permissions boundary caps an individual principal rather than enforcing an organization-wide encryption condition."},
{"id": "aa:dop-0041", "sources": ["aa:dop-0041"], "q": "An auditor requires that dozens of compliance controls (encryption at rest, access logging, no public access) be evaluated continuously across every account in the Organization, deployed and updated as a single versioned unit, with non-compliant resources remediated automatically. Which approach best meets this?", "options": [{"k": "A", "t": "Deploy an AWS Config organization conformance pack containing the managed rules and Systems Manager Automation remediations to all accounts and Regions"}, {"k": "B", "t": "Create the required AWS Config rules one at a time in each account through the console"}, {"k": "C", "t": "Use AWS Security Hub standards alone to evaluate and automatically remediate all of the controls"}, {"k": "D", "t": "Run a scheduled Lambda function that calls each account API to check the controls and fix violations"}], "answer": ["A"], "multi": false, "explanation": "An organization conformance pack bundles many Config rules and remediation actions into one versioned unit deployed across the Organization accounts and Regions, evaluating continuously and remediating through SSM Automation. Per-account manual rules are not a single unit, Security Hub focuses on aggregating findings rather than packaged remediation, and a custom Lambda is undifferentiated code to maintain."},
{"id": "aa:dop-0042", "sources": ["aa:dop-0042"], "q": "When Amazon GuardDuty raises a high-severity finding for an EC2 instance (for example, communication with a known command-and-control host), the team needs an automated response that isolates the instance and notifies responders, applied consistently across all accounts with the least custom infrastructure. Which design accomplishes this?", "options": [{"k": "A", "t": "Aggregate GuardDuty findings to a delegated administrator account and create an EventBridge rule filtered on high severity that invokes an SSM Automation or Lambda action to apply an isolation security group and notifies responders through SNS"}, {"k": "B", "t": "Have a security analyst review the GuardDuty console each shift and isolate affected instances manually"}, {"k": "C", "t": "Enable GuardDuty and rely on it to automatically quarantine the affected instance"}, {"k": "D", "t": "Create a CloudWatch alarm on a GuardDuty findings metric that emails the security team"}], "answer": ["A"], "multi": false, "explanation": "GuardDuty findings flow to EventBridge and can be centralized through the delegated administrator account; a rule filtered on severity can invoke automated isolation (SSM Automation or Lambda applying an isolation security group) and notify via SNS, consistently across the Organization. Manual review is not automated, GuardDuty itself does not remediate, and an email alarm performs no isolation."},
{"id": "aa:dop-0043", "sources": ["aa:dop-0043"], "q": "A security team needs a single, normalized view that aggregates and prioritizes findings from Amazon GuardDuty, Amazon Inspector, and AWS Config across all accounts in the Organization, scored against industry security standards, with new accounts included automatically. Which service should they use?", "options": [{"k": "A", "t": "AWS Security Hub with the organization integration and a delegated administrator, aggregating and normalizing findings against standards such as the AWS Foundational Security Best Practices"}, {"k": "B", "t": "Amazon Detective, to aggregate the findings and score them against the security standards"}, {"k": "C", "t": "Amazon CloudWatch Logs Insights queries run across each account findings"}, {"k": "D", "t": "AWS Trusted Advisor, which aggregates GuardDuty and Inspector findings across the Organization"}], "answer": ["A"], "multi": false, "explanation": "Security Hub aggregates and normalizes findings from GuardDuty, Inspector, Config, and more across accounts, with a delegated administrator and automatic enrollment of new accounts, scoring them against standards like the AWS FSBP. Detective is for investigation and root-cause analysis, Logs Insights is manual querying, and Trusted Advisor does not aggregate these security findings."},
{"id": "aa:dop-0044", "sources": ["aa:dop-0044"], "q": "Application teams must be able to create IAM roles for their own workloads, but those roles must never be granted permissions beyond an approved maximum, and the teams must not be able to escalate privileges by removing the control. Which combination enforces this?", "options": [{"k": "A", "t": "Grant the teams iam:CreateRole and iam:PutRolePolicy only under a condition that requires attaching a specific permissions boundary, and deny actions that remove or change that boundary"}, {"k": "B", "t": "Attach the approved policies directly to each team’s IAM users and trust them not to create broader roles"}, {"k": "C", "t": "Use an SCP that denies iam:CreateRole entirely so that no roles can be created"}, {"k": "D", "t": "Give the teams full IAM access and audit role creation with CloudTrail after the fact"}], "answer": ["A"], "multi": false, "explanation": "Granting role-creation permissions only when a required permissions boundary is attached (via an iam:PermissionsBoundary condition) caps what created roles can do, and denying changes to that boundary prevents privilege escalation. Direct policy attachment does not cap roles the team creates, a blanket SCP deny blocks the legitimate need to create roles, and after-the-fact auditing does not prevent escalation."},
{"id": "aa:dop-0045", "sources": ["aa:dop-0045"], "q": "A platform team must ensure container images are scanned for known vulnerabilities both when pushed and continuously as new CVEs are published, with findings centralized for the security team and images carrying Critical or High vulnerabilities prevented from being deployed. Which TWO actions accomplish this?", "options": [{"k": "A", "t": "Enable Amazon ECR enhanced scanning, powered by Amazon Inspector, which scans on push and continuously rescans as new CVEs are published, sending findings to AWS Security Hub"}, {"k": "B", "t": "Add a pipeline gate that queries the image scan findings and fails the deployment when Critical or High vulnerabilities are present"}, {"k": "C", "t": "Rely on ECR basic scanning, which continuously rescans images as new CVEs emerge"}, {"k": "D", "t": "Make the repositories public so the security team can review the images externally"}, {"k": "E", "t": "Disable image tag immutability so images can be overwritten with patched versions in place"}], "answer": ["A", "B"], "multi": true, "explanation": "ECR enhanced scanning with Inspector scans on push and continuously as new CVEs appear, routing findings to Security Hub, and a pipeline gate that checks those findings can block deployment of vulnerable images. ECR basic scanning runs on push only rather than continuously, public repositories are insecure, and disabling tag immutability harms traceability."},
{"id": "aa:dop-0046", "sources": ["aa:dop-0046"], "q": "A CodeBuild project must run dependency installation, then compilation, then a post-build image push as distinct ordered steps defined as code, versioned alongside the application source. Where and how should these steps be defined?", "options": [{"k": "A", "t": "In the phases section of a buildspec.yml stored in the source (install, pre_build, build, post_build), which CodeBuild runs in order"}, {"k": "B", "t": "As inline commands in the CodePipeline action configuration, which runs the build phases in order"}, {"k": "C", "t": "In EC2 user data on the CodeBuild compute fleet so each phase runs at launch"}, {"k": "D", "t": "In the CodeBuild project environment variables, one variable per phase"}], "answer": ["A"], "multi": false, "explanation": "The buildspec.yml phases (install, pre_build, build, post_build) define ordered build commands as code, versioned with the source. The pipeline action configuration wires stages rather than build phases, CodeBuild is managed and has no user-data fleet to script, and environment variables are not ordered commands."},
{"id": "aa:dop-0047", "sources": ["aa:dop-0047"], "q": "A CodePipeline must source from a GitHub repository, start automatically on a push, and authenticate through a managed, revocable integration without storing long-lived personal access tokens or SSH keys in the pipeline. Which source configuration meets this?", "options": [{"k": "A", "t": "An AWS CodeConnections connection to GitHub used as the CodePipeline source action, which triggers the pipeline via webhooks"}, {"k": "B", "t": "A CodePipeline source action that stores a GitHub personal access token in the action configuration"}, {"k": "C", "t": "A CodeBuild project that clones the repository with an embedded SSH deploy key on a fixed schedule"}, {"k": "D", "t": "An EventBridge scheduled rule that copies the repository into Amazon S3 every few minutes for the source stage"}], "answer": ["A"], "multi": false, "explanation": "A CodeConnections connection provides a managed, revocable GitHub integration with webhook triggering and no stored long-lived credentials. Storing a personal access token is long-lived credential management, and the scheduled clone or copy approaches add key management and latency."},
{"id": "aa:dop-0048", "sources": ["aa:dop-0048"], "q": "Several teams need a private, managed package repository for internal npm and Maven packages, with an upstream connection that proxies and caches public dependencies, and with access controlled through IAM. Which service meets these requirements with the least operational effort?", "options": [{"k": "A", "t": "AWS CodeArtifact with an upstream repository connected to the public npm and Maven registries"}, {"k": "B", "t": "A self-managed Nexus or Artifactory server on Amazon EC2 behind an internal load balancer"}, {"k": "C", "t": "Amazon ECR repositories used to store the npm and Maven packages"}, {"k": "D", "t": "An Amazon S3 bucket of package files exposed as a static website"}], "answer": ["A"], "multi": false, "explanation": "CodeArtifact is a managed package repository for npm, Maven, and more, with upstream connections that proxy and cache public packages and IAM-based access control, with minimal operations. A self-managed server adds operational effort, ECR stores container images rather than language packages, and an S3 static site is not a package manager."},
{"id": "aa:dop-0049", "sources": ["aa:dop-0049"], "q": "A team must release a new application version on an EC2 Auto Scaling group so that a complete replacement fleet is provisioned and validated before any production traffic is shifted, traffic moves over in one step, and rollback is immediate. Which CodeDeploy deployment type and setting fit best?", "options": [{"k": "A", "t": "A blue/green deployment that provisions a replacement Auto Scaling group, validates it, reroutes the load balancer in one step, and keeps the original group for immediate rollback"}, {"k": "B", "t": "An in-place deployment with a high minimum-healthy-hosts percentage"}, {"k": "C", "t": "An in-place deployment using the CodeDeployDefault.OneAtATime configuration"}, {"k": "D", "t": "A blue/green deployment that terminates the original instances immediately after rerouting traffic"}], "answer": ["A"], "multi": false, "explanation": "A blue/green deployment provisions and validates a replacement fleet behind the load balancer before rerouting traffic in one step, and keeping the original instances enables immediate rollback. In-place options modify existing instances with no separate validated fleet, and terminating the originals immediately removes the fast rollback path."},
{"id": "aa:dop-0050", "sources": ["aa:dop-0050"], "q": "A pipeline stage runs four independent test suites one after another, making it the slowest part of the pipeline. The team wants to cut wall-clock time by running the suites concurrently while keeping a single pipeline. Which TWO approaches achieve concurrency?", "options": [{"k": "A", "t": "Define the four test actions in the same stage with the same runOrder so CodePipeline runs them in parallel"}, {"k": "B", "t": "Use a CodeBuild batch build to run the suites as concurrent build configurations within one action"}, {"k": "C", "t": "Increase the CodeBuild compute type to the largest size and keep the suites sequential"}, {"k": "D", "t": "Add manual approval actions between the suites to control the flow"}, {"k": "E", "t": "Raise the pipeline artifact store size limit"}], "answer": ["A", "B"], "multi": true, "explanation": "Actions that share the same runOrder in a stage run in parallel, and CodeBuild batch builds run multiple configurations concurrently within one action; both reduce wall-clock time. A larger compute type does not make the suites concurrent, approvals serialize them further, and the artifact store size is unrelated."},
{"id": "aa:dop-0051", "sources": ["aa:dop-0051"], "q": "After each CodeBuild run, the team needs structured pass/fail results and historical trends of their JUnit test output visible in the console, with failed builds clearly tied to the failing tests, without building a separate reporting system. What should they configure?", "options": [{"k": "A", "t": "Add a reports section to the buildspec that points to the JUnit result files so CodeBuild creates a test report group with pass/fail trends"}, {"k": "B", "t": "Print the test summary to the build logs and read the logs after each run"}, {"k": "C", "t": "Upload the raw result files to Amazon S3 and build a custom dashboard from them"}, {"k": "D", "t": "Publish a custom CloudWatch metric of the number of passed tests from a post_build command"}], "answer": ["A"], "multi": false, "explanation": "A buildspec reports section parses JUnit and other result formats into a CodeBuild test report group that shows pass/fail trends and ties failures to builds, with no separate system. Build logs give no structured trend, an S3-plus-custom-dashboard is a separate system, and a custom metric does not show per-test results."},
{"id": "aa:dop-0052", "sources": ["aa:dop-0052"], "q": "To make Amazon ECS deployments fully traceable and to avoid the stale-image problems caused by mutable tags, each build must publish an image that maps unambiguously to the exact source revision, and deployments must reference an image that cannot change underneath a running service. Which approach is best?", "options": [{"k": "A", "t": "Tag the image with the Git commit SHA, enable tag immutability on the ECR repository, and reference the image by digest in the ECS task definition"}, {"k": "B", "t": "Always push and deploy the latest tag and rely on ECS to pull the newest image"}, {"k": "C", "t": "Tag images with an incrementing build number but allow the tag to be overwritten when a build is re-run"}, {"k": "D", "t": "Reference images by repository name only and let ECS choose a tag at deployment time"}], "answer": ["A"], "multi": false, "explanation": "Tagging by commit SHA with tag immutability and referencing the image by digest gives traceable, immutable deployments that cannot change underneath a running service. Reusing latest or overwritable tags is mutable and causes stale-image problems, and referencing without a specific tag or digest is ambiguous."},
{"id": "aa:dop-0053", "sources": ["aa:dop-0053"], "q": "An application on AWS Elastic Beanstalk must be released so that the new version is deployed to a separate, fully running environment, validated, and then cut into production with near-zero downtime and the ability to revert immediately if problems appear. Which approach should the team use?", "options": [{"k": "A", "t": "Deploy the new version to a clone environment and perform a blue/green deployment by swapping the environment URLs (CNAME swap) after validation"}, {"k": "B", "t": "Use the all-at-once deployment policy on the existing environment"}, {"k": "C", "t": "Use the rolling deployment policy on the existing environment"}, {"k": "D", "t": "Terminate the existing environment and recreate it with the new version"}], "answer": ["A"], "multi": false, "explanation": "Beanstalk blue/green deploys the new version to a separate environment, validates it, and swaps CNAMEs for near-zero-downtime cutover with immediate rollback by swapping back. All-at-once causes downtime, rolling modifies the running environment in place, and recreate causes downtime and loses the fast revert."},
{"id": "aa:dop-0054", "sources": ["aa:dop-0054"], "q": "On AWS Elastic Beanstalk, a team wants each deployment to launch an entirely new set of instances running the new version and switch to them only if they pass health checks, never modifying existing instances in place, so a failed deployment leaves the environment fully intact. Which deployment policy meets this?", "options": [{"k": "A", "t": "Immutable"}, {"k": "B", "t": "Rolling"}, {"k": "C", "t": "Rolling with an additional batch"}, {"k": "D", "t": "All at once"}], "answer": ["A"], "multi": false, "explanation": "The immutable policy launches a full new set of instances in a temporary group and shifts to them only after they pass health checks, never modifying existing instances, so a failed deployment leaves the original instances untouched. Rolling, rolling with an additional batch, and all at once modify existing capacity in place."},
{"id": "aa:dop-0055", "sources": ["aa:dop-0055"], "q": "A release must deploy the same CloudFormation stack to three Regions from one pipeline, with the deployments running as pipeline actions and surfacing failure status per Region, using the least custom scripting. Which approach fits best?", "options": [{"k": "A", "t": "Add CloudFormation deploy actions (or a CloudFormation StackSets action) to the pipeline, one targeting each Region, using cross-Region action artifacts"}, {"k": "B", "t": "Run a single CodeBuild action that loops over the Regions and calls the AWS CLI to deploy each stack"}, {"k": "C", "t": "Create three separate pipelines triggered independently and reconcile their results manually"}, {"k": "D", "t": "Deploy the stack in one Region and rely on CloudFormation to replicate it to the other Regions"}], "answer": ["A"], "multi": false, "explanation": "CodePipeline supports cross-Region deploy actions and a StackSets action, so one pipeline can deploy to multiple Regions and surface per-action status with minimal scripting. A CLI loop is custom scripting, separate pipelines are not one pipeline, and CloudFormation does not replicate stacks across Regions."},
{"id": "aa:dop-0056", "sources": ["aa:dop-0056"], "q": "A company runs self-managed Jenkins controllers and agents on EC2 for builds and wants to remove the burden of patching, scaling, and securing the build fleet while reusing its existing build scripts and integrating with CodePipeline. Which change achieves this with the least operational overhead?", "options": [{"k": "A", "t": "Move build execution to AWS CodeBuild, defining the existing build steps in a buildspec and using CodeBuild as a CodePipeline build action"}, {"k": "B", "t": "Keep Jenkins but move the agents into a larger Auto Scaling group that the team continues to patch"}, {"k": "C", "t": "Containerize Jenkins and run it on an Amazon EKS cluster that the team operates"}, {"k": "D", "t": "Replace the builds with AWS Lambda functions that compile the application code"}], "answer": ["A"], "multi": false, "explanation": "CodeBuild is fully managed and scales per build, eliminating fleet patching, scaling, and securing while running the existing steps via buildspec and integrating as a CodePipeline action. Larger Jenkins agents and Jenkins on EKS keep the operational burden, and Lambda is not a general-purpose build environment."},
{"id": "aa:dop-0057", "sources": ["aa:dop-0057"], "q": "A Lambda function is deployed with AWS CodeDeploy using canary traffic shifting. Before any production traffic is shifted to the new version, the team must run an automated check that invokes the new version and aborts the deployment if the check fails. How should this be implemented?", "options": [{"k": "A", "t": "Add a BeforeAllowTraffic hook in the AppSpec that invokes a validation Lambda function, returning a failure result to abort the deployment before traffic shifts"}, {"k": "B", "t": "Add an AfterAllowTraffic hook that invokes a validation Lambda function to check the new version"}, {"k": "C", "t": "Rely solely on the CloudWatch alarm rollback with no pre-traffic validation hook"}, {"k": "D", "t": "Validate the new version manually in the console between deployments"}], "answer": ["A"], "multi": false, "explanation": "For Lambda CodeDeploy deployments, a BeforeAllowTraffic lifecycle hook invokes a validation Lambda before any traffic is shifted, and a failure result aborts the deployment. AfterAllowTraffic runs after traffic begins shifting, alarm-based rollback only reacts after traffic moves, and manual validation is not automated."},
{"id": "aa:dop-0058", "sources": ["aa:dop-0058"], "q": "A pipeline S3 artifact store is encrypted with the default AWS managed key. A deploy action running in another account fails with an access-denied error while decrypting the artifacts. What is the correct fix?", "options": [{"k": "A", "t": "Re-encrypt the artifact bucket with a customer-managed KMS key, grant the other account role usage of that key in the key policy, and grant the role bucket read and kms:Decrypt permissions"}, {"k": "B", "t": "Make the artifact bucket public so the other account can read the objects"}, {"k": "C", "t": "Edit the aws/s3 AWS managed key policy to allow the other account to decrypt"}, {"k": "D", "t": "Copy the artifacts to the other account by manual download between deployments"}], "answer": ["A"], "multi": false, "explanation": "The default AWS managed key cannot be shared across accounts because its key policy is not editable, so the artifacts must be encrypted with a customer-managed KMS key whose policy grants the other account, with the role also granted bucket read and kms:Decrypt. Public buckets and manual copying are insecure or unworkable, and the AWS managed key policy cannot be modified."},
{"id": "aa:dop-0059", "sources": ["aa:dop-0059"], "q": "A release pipeline must automatically run end-to-end tests against a deployed staging environment, block promotion if the tests fail, and require an authorized approver to sign off before the production deployment. Which TWO CodePipeline elements implement these controls?", "options": [{"k": "A", "t": "A CodeBuild test action that runs the end-to-end tests against staging and fails the stage when tests fail"}, {"k": "B", "t": "A manual approval action before the production deploy stage, restricted to the approver group through IAM"}, {"k": "C", "t": "A scheduled pipeline execution each night that promotes regardless of test results"}, {"k": "D", "t": "Disabling CloudWatch alarms during the deployment to reduce noise"}, {"k": "E", "t": "Granting all developers approval permission so releases are never blocked"}], "answer": ["A", "B"], "multi": true, "explanation": "A CodeBuild test action gates promotion on the end-to-end results, and a manual approval action restricted by IAM enforces authorized sign-off before production. A scheduled promotion does not gate on tests, disabling alarms is harmful, and granting everyone approval defeats the control."},
{"id": "aa:dop-0060", "sources": ["aa:dop-0060"], "q": "A team already has a repository association in Amazon CodeGuru Reviewer that was created before November 7, 2025. Which service can continue providing automated code quality and security recommendations for pull requests?", "options": [{"k": "A", "t": "Amazon CodeGuru Reviewer"}, {"k": "B", "t": "Amazon GuardDuty"}, {"k": "C", "t": "AWS Config"}, {"k": "D", "t": "Amazon Inspector"}], "answer": ["A"], "multi": false, "explanation": "CodeGuru Reviewer can continue reviewing repositories that were associated before the availability change. As of November 7, 2025, customers cannot create new repository associations, so it is not a valid greenfield recommendation. GuardDuty and Inspector detect threats or vulnerabilities; Config evaluates configuration compliance."},
{"id": "aa:dop-0061", "sources": ["aa:dop-0061"], "q": "A CodeBuild project builds container images in the standard CodeBuild environment and is slow because it rebuilds every Docker layer on each run. Which configuration speeds up the image builds while still allowing the Docker daemon to run?", "options": [{"k": "A", "t": "Run the build in privileged mode and enable local caching with the Docker layer cache mode so unchanged layers are reused"}, {"k": "B", "t": "Disable privileged mode and enable local Docker layer caching"}, {"k": "C", "t": "Configure an Amazon S3 source cache for the Git repository"}, {"k": "D", "t": "Switch to a larger compute type with no caching configured"}], "answer": ["A"], "multi": false, "explanation": "Building Docker images in CodeBuild requires privileged mode, and enabling local caching with the Docker layer cache reuses unchanged layers to speed builds. Disabling privileged mode prevents the Docker daemon from running, a source cache does not cache image layers, and a larger compute type still rebuilds every layer."},
{"id": "aa:dop-0062", "sources": ["aa:dop-0062"], "q": "A pipeline must start only for pushes to branches matching release/* and for tags matching v*, and must ignore all other pushes, using native CodePipeline triggering. How should this be configured?", "options": [{"k": "A", "t": "Configure CodePipeline triggers on the source connection with git push filters that include the release/* branch pattern and the v* tag pattern"}, {"k": "B", "t": "Start the pipeline on every push and add a first stage that exits early when the ref does not match"}, {"k": "C", "t": "Use periodic source polling plus a Lambda function that decides whether to continue based on the branch"}, {"k": "D", "t": "Create a separate pipeline per branch and disable the unwanted ones manually"}], "answer": ["A"], "multi": false, "explanation": "CodePipeline triggers support git push filters on branches and tags, so only matching refs start the pipeline natively. Starting on every push wastes executions, polling plus a Lambda is custom and slower, and per-branch pipelines toggled manually are unmaintainable."},
{"id": "aa:dop-0063", "sources": ["aa:dop-0063"], "q": "An Amazon ECS blue/green deployment through CodeDeploy must automatically roll back to the previous task set if the application error-rate metric breaches a threshold during the traffic shift, with no manual intervention. What should be configured?", "options": [{"k": "A", "t": "Associate a CloudWatch alarm on the error-rate metric with the CodeDeploy deployment group and enable automatic rollback on alarm"}, {"k": "B", "t": "Set a long ECS health check grace period so failures are tolerated during the shift"}, {"k": "C", "t": "Schedule a Lambda function to redeploy the previous task definition every hour during releases"}, {"k": "D", "t": "Increase the ECS service desired count so healthy tasks outnumber failing ones"}], "answer": ["A"], "multi": false, "explanation": "CodeDeploy can monitor an associated CloudWatch alarm during the deployment and automatically roll back to the original task set when it breaches, with no manual action. A long grace period tolerates failures rather than rolling back, a scheduled Lambda is coarse and custom, and raising the desired count does not roll back."},
{"id": "aa:dop-0064", "sources": ["aa:dop-0064"], "q": "During stack creation, a CloudFormation template must obtain a value from a third-party system that has no native CloudFormation resource type, fail the stack if the lookup fails, and clean up the external registration when the stack is deleted. Which mechanism should be used?", "options": [{"k": "A", "t": "A Lambda-backed custom resource that handles Create, Update, and Delete and signals success or failure back to CloudFormation"}, {"k": "B", "t": "A nested stack that imports the value from another stack"}, {"k": "C", "t": "A CloudFormation macro that transforms the template to include the value"}, {"k": "D", "t": "An SSM parameter holding a hard-coded value that is updated manually"}], "answer": ["A"], "multi": false, "explanation": "A Lambda-backed custom resource runs logic on Create, Update, and Delete, so it can call the third-party system, fail the stack on error, and clean up the registration on delete. Nested stacks compose templates, macros transform templates before provisioning rather than calling external systems during it, and a manual parameter has no lifecycle handling."},
{"id": "aa:dop-0065", "sources": ["aa:dop-0065"], "q": "A platform team must automatically inject a standard set of tags and a logging configuration into the resources of submitted CloudFormation templates, applying their own logic before the resources are created, without requiring each team to edit its templates. Which capability should they build?", "options": [{"k": "A", "t": "A CloudFormation macro (a Lambda-backed transform) that processes each template and adds the tags and logging configuration before deployment"}, {"k": "B", "t": "A Lambda-backed custom resource that each team references in its template"}, {"k": "C", "t": "A stack policy applied to each stack"}, {"k": "D", "t": "An AWS Config rule that adds the tags to resources"}], "answer": ["A"], "multi": false, "explanation": "A macro is a Lambda-backed transform that processes the template and can inject tags and configuration into resources before deployment, centrally and without each team editing templates. A custom resource acts during provisioning and must be added to each template, a stack policy protects rather than adds resources, and Config remediates after creation."},
{"id": "aa:dop-0066", "sources": ["aa:dop-0066"], "q": "EC2 instances are configured with AWS::CloudFormation::Init metadata. When the stack is updated with new metadata such as an updated configuration file, the running instances must apply the change in place, without being replaced and without manual intervention. What enables this?", "options": [{"k": "A", "t": "Run the cfn-hup daemon on the instances, configured to detect metadata changes and re-run cfn-init through a hook"}, {"k": "B", "t": "Add a DependsOn from the instance to its launch template"}, {"k": "C", "t": "Set an UpdatePolicy on the instance resource"}, {"k": "D", "t": "Set a DeletionPolicy of Retain on the instance"}], "answer": ["A"], "multi": false, "explanation": "cfn-hup watches for changes to the instance metadata and runs configured hooks, such as re-running cfn-init, to apply updates in place with no replacement or manual action. DependsOn only orders creation, UpdatePolicy does not reapply metadata to a standalone instance, and DeletionPolicy governs deletion behavior."},
{"id": "aa:dop-0067", "sources": ["aa:dop-0067"], "q": "A CloudFormation stack contains a production database that must never be replaced or deleted by a stack update, while the rest of the stack can still be updated normally. Which mechanism enforces this during updates?", "options": [{"k": "A", "t": "A stack policy that denies Update:Replace and Update:Delete on the database resource while allowing updates to other resources"}, {"k": "B", "t": "Termination protection enabled on the stack"}, {"k": "C", "t": "A DeletionPolicy of Retain on the database resource"}, {"k": "D", "t": "A change set reviewed before each update"}], "answer": ["A"], "multi": false, "explanation": "A stack policy restricts which update actions are allowed on specific resources, so denying Update:Replace and Update:Delete on the database protects it during updates while other resources update normally. Termination protection only blocks stack deletion, DeletionPolicy Retain affects removal rather than preventing a replacing update, and a change set previews changes but does not enforce a block."},
{"id": "aa:dop-0068", "sources": ["aa:dop-0068"], "q": "A team wants to define infrastructure using a general-purpose programming language with reusable, parameterized components and unit tests, while still deploying through AWS CloudFormation so it keeps drift detection and rollback. Which tool fits best?", "options": [{"k": "A", "t": "AWS Cloud Development Kit (CDK), which synthesizes CloudFormation from constructs written in a programming language and deploys through CloudFormation"}, {"k": "B", "t": "Hand-written raw CloudFormation JSON templates"}, {"k": "C", "t": "Terraform with a custom remote state backend"}, {"k": "D", "t": "AWS Service Catalog products only"}], "answer": ["A"], "multi": false, "explanation": "The CDK lets you author infrastructure in a programming language with reusable constructs and unit tests, synthesizing CloudFormation so you keep drift detection and rollback. Raw JSON lacks programmatic constructs, Terraform does not deploy through CloudFormation, and Service Catalog distributes approved products rather than authoring constructs."},
{"id": "aa:dop-0069", "sources": ["aa:dop-0069"], "q": "Central IT must let application teams self-service-provision infrastructure, but only from a set of approved, versioned products with constrained parameters (for example, only certain instance types and Regions), and must track who launched what. Which service provides this?", "options": [{"k": "A", "t": "AWS Service Catalog, publishing approved products with launch and template constraints and recording provisioned products per user"}, {"k": "B", "t": "Give teams direct CloudFormation access and maintain a wiki of approved templates"}, {"k": "C", "t": "AWS Marketplace subscriptions for the required infrastructure"}, {"k": "D", "t": "An Amazon S3 bucket of approved templates that teams copy from"}], "answer": ["A"], "multi": false, "explanation": "Service Catalog publishes approved, versioned products with launch and template constraints (such as allowed instance types and Regions) and tracks provisioned products per user. A wiki or S3 bucket of templates does not enforce constraints or track launches, and Marketplace is for third-party software."},
{"id": "aa:dop-0070", "sources": ["aa:dop-0070"], "q": "An operations team repeatedly performs a multi-step maintenance procedure (quiesce the application, snapshot the volume, apply a patch, restart, verify) and wants it codified as a versioned, auditable workflow that can run on demand, on a schedule, or in response to an event, with branching and error handling. Which service should they use?", "options": [{"k": "A", "t": "AWS Systems Manager Automation runbooks, which codify multi-step procedures with steps, branching, and error handling, runnable on demand, on a schedule, or from events"}, {"k": "B", "t": "A single AWS Lambda function that contains the entire procedure as one script"}, {"k": "C", "t": "A documented manual checklist kept in a team wiki"}, {"k": "D", "t": "An AWS Config rule with an automatic remediation action"}], "answer": ["A"], "multi": false, "explanation": "SSM Automation runbooks codify multi-step operational procedures as versioned documents with branching and error handling, runnable on demand, on a schedule, or from events, with auditing. A single Lambda script is less auditable and harder to branch or gate, a wiki checklist is manual, and Config remediation targets compliance violations rather than arbitrary scheduled procedures."},
{"id": "aa:dop-0071", "sources": ["aa:dop-0071"], "q": "On AWS Elastic Beanstalk, a team must customize the environment (install OS packages, set web server options) declaratively, versioned with the application source so the same customization is applied on every deployment and in every environment. Which mechanism is used?", "options": [{"k": "A", "t": ".ebextensions configuration files included in the application source bundle"}, {"k": "B", "t": "Manual changes made over SSH after each deployment"}, {"k": "C", "t": "A custom AMI that the team rebuilds for each configuration change"}, {"k": "D", "t": "Environment properties set only in the Elastic Beanstalk console"}], "answer": ["A"], "multi": false, "explanation": ".ebextensions files in the source bundle declaratively customize the environment (packages, options) and are versioned with the application, so the same customization applies on every deployment and environment. Manual SSH changes are not repeatable, a custom AMI is heavier and not source-versioned configuration, and console environment properties cover only settings such as environment variables."},
{"id": "aa:dop-0072", "sources": ["aa:dop-0072"], "q": "An application has many non-sensitive configuration values that change occasionally and a few database credentials that must be rotated automatically. The team wants the lowest cost for the bulk configuration and managed rotation for the credentials. Which TWO choices fit each need?", "options": [{"k": "A", "t": "Store the non-sensitive configuration values in Systems Manager Parameter Store standard parameters, which have no per-secret charge"}, {"k": "B", "t": "Store the database credentials in AWS Secrets Manager and enable managed rotation"}, {"k": "C", "t": "Store the database credentials in Parameter Store standard parameters and rotate them with a custom Lambda function"}, {"k": "D", "t": "Store all values, including the credentials, in Secrets Manager to keep everything in one place"}, {"k": "E", "t": "Hard-code the configuration values in the application to avoid lookups"}], "answer": ["A", "B"], "multi": true, "explanation": "Parameter Store standard parameters store bulk non-sensitive configuration at the lowest cost, and Secrets Manager provides managed rotation for the database credentials. Custom Lambda rotation is not managed rotation, putting all values in Secrets Manager costs more for bulk configuration, and hard-coding is not manageable."},
{"id": "aa:dop-0073", "sources": ["aa:dop-0073"], "q": "A team wants a CloudFormation stack creation or update to automatically roll back if specified CloudWatch alarms (for example, high application error rates as new resources come online) breach within a monitoring window after the resources are created. What should they configure?", "options": [{"k": "A", "t": "A rollback configuration with rollback triggers referencing the CloudWatch alarms and a monitoring time period on the stack operation"}, {"k": "B", "t": "A stack policy that denies updates to the affected resources"}, {"k": "C", "t": "Termination protection on the stack"}, {"k": "D", "t": "A CreationPolicy with ResourceSignal on every resource"}], "answer": ["A"], "multi": false, "explanation": "A rollback configuration with rollback triggers monitors the specified CloudWatch alarms for a defined period during the stack operation and rolls back if they breach. A stack policy restricts updates, termination protection prevents deletion, and CreationPolicy with ResourceSignal gates on success signals rather than CloudWatch alarms."},
{"id": "aa:dop-0074", "sources": ["aa:dop-0074"], "q": "A single CloudFormation template has grown to thousands of lines mixing networking, security, and application tiers, and is hard to maintain and reuse. The team wants to split it into independently maintained, reusable templates that a parent template composes and deploys as one stack operation. Which approach fits?", "options": [{"k": "A", "t": "Refactor the template into nested stacks, each owning one tier, referenced and orchestrated by a parent stack"}, {"k": "B", "t": "Split the resources into multiple independent stacks wired together with Export and Fn::ImportValue"}, {"k": "C", "t": "Keep one template but add comments to organize the sections"}, {"k": "D", "t": "Convert the template into a sequence of AWS CLI commands in a shell script"}], "answer": ["A"], "multi": false, "explanation": "Nested stacks split a large template into reusable child templates orchestrated by a parent and deployed as one stack operation, improving maintainability and reuse. Cross-stack exports create independently managed stacks with tighter coupling, comments do not modularize, and a CLI script abandons CloudFormation management."},
{"id": "aa:dop-0075", "sources": ["aa:dop-0075"], "q": "A platform team wants to publish a standardized, versioned building block (for example, an encrypted S3 bucket with logging and a bucket policy) that many teams reference as a single resource type in their CloudFormation templates, with central updates to the building block. Which CloudFormation feature provides this?", "options": [{"k": "A", "t": "CloudFormation modules registered in the CloudFormation registry and referenced as a resource type"}, {"k": "B", "t": "Nested stacks that each team references from its own template"}, {"k": "C", "t": "A shared Mappings section copied into each template"}, {"k": "D", "t": "A Lambda-backed custom resource implemented separately by each team"}], "answer": ["A"], "multi": false, "explanation": "CloudFormation modules are versioned, reusable building blocks registered in the registry and referenced as a resource type, with central versioning. Nested stacks are reusable but referenced as stacks rather than a registered resource type, Mappings are static lookups, and a custom resource is per-team code rather than a registered module."},
{"id": "aa:dop-0076", "sources": ["aa:dop-0076"], "q": "A company still has EC2 instances that were managed by AWS OpsWorks Stacks. The service reached end of life, and the company needs a supported AWS-native operating model. Which approach follows AWS migration guidance?", "options": [{"k": "A", "t": "Migrate the workload to CloudFormation, Systems Manager, and EC2 Auto Scaling; use Systems Manager Application Manager and Automation for operations"}, {"k": "B", "t": "Create new OpsWorks Stacks and keep using the retired control plane"}, {"k": "C", "t": "Replace configuration management with Amazon EventBridge only"}, {"k": "D", "t": "Use AWS Config as the application deployment engine"}], "answer": ["A"], "multi": false, "explanation": "OpsWorks Stacks was disabled for new and existing customers after its May 26, 2024 end of life. AWS migration guidance uses CloudFormation, Systems Manager, and Auto Scaling, with Application Manager and Automation for ongoing operations. The other services do not recreate a supported configuration-management control plane."},
{"id": "aa:dop-0077", "sources": ["aa:dop-0077"], "q": "Dev, test, and prod environments use the same set of configuration keys with different values. The team wants to organize the values by environment, retrieve all of an environment’s values in one call by path, keep a history of changes, and reference them from CloudFormation and ECS task definitions. Which approach fits best?", "options": [{"k": "A", "t": "Store the values as Systems Manager Parameter Store hierarchical parameters (for example /app/prod/...) and retrieve them with GetParametersByPath, using parameter versioning"}, {"k": "B", "t": "Store one JSON file per environment in Amazon S3 and parse it in the application"}, {"k": "C", "t": "Bake the values into a separate AMI per environment as environment variables"}, {"k": "D", "t": "Store the values in a DynamoDB table keyed by environment and configuration key"}], "answer": ["A"], "multi": false, "explanation": "Parameter Store hierarchical parameters organize values by environment path, support GetParametersByPath to fetch a whole environment in one call, keep version history, and integrate natively with CloudFormation and ECS. An S3 JSON file lacks per-key versioning and path retrieval, baked-in AMI variables are not centrally managed, and DynamoDB lacks the native versioning, path retrieval, and integrations."},
{"id": "aa:dop-0078", "sources": ["aa:dop-0078"], "q": "A globally distributed application needs a fully managed key-value datastore that serves low-latency reads and writes from multiple Regions simultaneously, replicates changes automatically between Regions, and keeps serving in each Region if another Region fails. Which option meets this?", "options": [{"k": "A", "t": "Amazon DynamoDB global tables, providing multi-Region active-active replication"}, {"k": "B", "t": "A DynamoDB table in one Region that clients in other Regions access cross-Region"}, {"k": "C", "t": "An Amazon RDS Multi-AZ instance with a cross-Region read replica"}, {"k": "D", "t": "A self-managed key-value store replicated by a custom process across EC2 instances in two Regions"}], "answer": ["A"], "multi": false, "explanation": "DynamoDB global tables provide fully managed multi-Region active-active replication with low-latency local reads and writes and continued operation if a Region fails. A single-Region table adds latency and a single point of failure, an RDS read replica is read-only and not active-active for writes, and a self-managed store is operationally heavy."},
{"id": "aa:dop-0079", "sources": ["aa:dop-0079"], "q": "Objects written to an S3 bucket must be replicated automatically to a bucket in another Region for disaster recovery and lower-latency regional reads, including replicating delete markers, while objects that already exist before replication is enabled must also be brought into sync. Which approach meets this?", "options": [{"k": "A", "t": "Enable S3 Cross-Region Replication with versioning on both buckets and a rule that replicates delete markers, and run S3 Batch Replication for the pre-existing objects"}, {"k": "B", "t": "Enable S3 Transfer Acceleration on the source bucket"}, {"k": "C", "t": "Turn on S3 server access logging and copy the access logs to the second Region"}, {"k": "D", "t": "Apply S3 Intelligent-Tiering so objects move to the second Region automatically"}], "answer": ["A"], "multi": false, "explanation": "Cross-Region Replication with versioning on both buckets replicates new objects automatically and can replicate delete markers, and S3 Batch Replication handles objects that existed before replication was enabled. Transfer Acceleration only speeds uploads, access logging copies logs rather than data, and Intelligent-Tiering changes storage class within a Region."},
{"id": "aa:dop-0080", "sources": ["aa:dop-0080"], "q": "A production Amazon RDS for PostgreSQL database must automatically fail over to a standby with no committed-data loss if its Availability Zone fails, while staying in a single Region. Which configuration provides this, and what is its replication mode?", "options": [{"k": "A", "t": "An RDS Multi-AZ deployment, which keeps a synchronous standby in another AZ and fails over automatically with no committed-data loss"}, {"k": "B", "t": "A single-AZ instance with frequent automated snapshots used for a fast restore"}, {"k": "C", "t": "A cross-Region read replica that is promoted on failure"}, {"k": "D", "t": "Two single-AZ instances kept in sync by application-level dual writes"}], "answer": ["A"], "multi": false, "explanation": "RDS Multi-AZ maintains a synchronous standby in another AZ within the Region and fails over automatically with no committed-data loss. Snapshot restore is not automatic failover and risks data loss, a cross-Region read replica is asynchronous and cross-Region, and application dual writes are custom and error-prone."},
{"id": "aa:dop-0081", "sources": ["aa:dop-0081"], "q": "A reporting workload runs heavy read queries that overload the primary Amazon RDS instance and slow down writes. The reporting reads can tolerate slight staleness. How should the team scale reads while protecting write performance, with the least application change?", "options": [{"k": "A", "t": "Add one or more RDS read replicas and direct the reporting read traffic to a read-replica endpoint"}, {"k": "B", "t": "Enable Multi-AZ and send the reporting reads to the standby instance"}, {"k": "C", "t": "Increase the primary backup retention period and take snapshots more frequently"}, {"k": "D", "t": "Run the reporting queries against the most recent automated snapshot"}], "answer": ["A"], "multi": false, "explanation": "Read replicas offload read traffic from the primary and tolerate slight staleness, protecting write performance with minimal application change by pointing reads at the replica endpoint. The Multi-AZ standby is not readable, backups and snapshots do not offload reads, and snapshots are not live-queryable."},
{"id": "aa:dop-0082", "sources": ["aa:dop-0082"], "q": "A producer service occasionally generates bursts far above what the downstream consumer can process, causing dropped work and failures during spikes. The team wants to absorb the bursts, let the consumer process at its own rate, and retain messages that repeatedly fail processing for later inspection. Which design is best?", "options": [{"k": "A", "t": "Place an Amazon SQS queue between the producer and the consumer, with a dead-letter queue for messages that exceed the maximum receive count"}, {"k": "B", "t": "Have the producer call the consumer synchronously and retry until each call succeeds"}, {"k": "C", "t": "Scale the consumer to a fixed large size that can handle peak load at all times"}, {"k": "D", "t": "Drop messages that arrive faster than the consumer can process them"}], "answer": ["A"], "multi": false, "explanation": "An SQS queue buffers bursts so the consumer processes at its own rate, and a dead-letter queue retains messages that repeatedly fail for inspection. Synchronous retries propagate backpressure, fixed over-provisioning is costly and still lacks a failure buffer, and dropping messages loses work."},
{"id": "aa:dop-0083", "sources": ["aa:dop-0083"], "q": "An Auto Scaling group launches instances that take 6 to 8 minutes to boot and initialize before they can serve traffic, so the group cannot scale out fast enough during sudden, unpredictable demand spikes. Which feature reduces scale-out latency by keeping pre-initialized instances ready?", "options": [{"k": "A", "t": "Auto Scaling group warm pools, which keep pre-initialized, typically stopped, instances ready to bring into service quickly"}, {"k": "B", "t": "A longer health check grace period on the group"}, {"k": "C", "t": "Predictive scaling, without otherwise addressing the boot time"}, {"k": "D", "t": "A shorter scaling cooldown period"}], "answer": ["A"], "multi": false, "explanation": "Warm pools keep pre-initialized instances ready so scale-out brings them into service quickly, cutting the boot and initialization latency. A grace period and cooldown do not reduce boot time, and predictive scaling addresses known recurring patterns rather than sudden, unpredictable spikes."},
{"id": "aa:dop-0084", "sources": ["aa:dop-0084"], "q": "An application load follows a strong, repeating daily and weekly pattern with predictable morning ramps that currently cause brief under-provisioning because reactive scaling lags the ramp. The team wants capacity provisioned ahead of the forecasted demand with the least ongoing tuning. Which approach fits best?", "options": [{"k": "A", "t": "Auto Scaling predictive scaling, which forecasts demand from historical patterns and provisions capacity ahead of the ramp"}, {"k": "B", "t": "A target tracking policy on CPU only, which scales after utilization rises"}, {"k": "C", "t": "Scheduled scaling actions that the team hand-tunes each week to the expected pattern"}, {"k": "D", "t": "A fixed desired capacity sized for the daily peak at all times"}], "answer": ["A"], "multi": false, "explanation": "Predictive scaling forecasts demand from historical daily and weekly patterns and provisions capacity ahead of the ramp, addressing the lag of reactive scaling with little ongoing tuning. Target tracking is reactive, hand-tuned scheduled scaling is high-maintenance, and fixed peak capacity is wasteful off-peak."},
{"id": "aa:dop-0085", "sources": ["aa:dop-0085"], "q": "A web tier behind an Auto Scaling group loses user sessions whenever an instance is replaced during scaling or deployments, because sessions are stored in instance memory. The team wants instances to be fully replaceable without losing sessions, with low-latency session access. Where should session state be stored?", "options": [{"k": "A", "t": "In an external low-latency store such as Amazon ElastiCache or a DynamoDB session store, keeping the instances stateless"}, {"k": "B", "t": "On each instance local disk, backed up periodically to Amazon S3"}, {"k": "C", "t": "Pinned to a specific instance using load balancer sticky sessions, with no external store"}, {"k": "D", "t": "In a file on a single shared EBS volume attached to one instance"}], "answer": ["A"], "multi": false, "explanation": "Externalizing session state to ElastiCache or DynamoDB keeps the tier stateless so any instance can serve any request and replacements lose no sessions, with low-latency access. Local disk and single-EBS storage tie state to an instance, and sticky sessions still lose state when the pinned instance is replaced."},
{"id": "aa:dop-0086", "sources": ["aa:dop-0086"], "q": "An Amazon ECS rolling deployment must automatically stop and roll back to the last stable task set if the new tasks repeatedly fail to start or fail health checks, without requiring a separate CodeDeploy blue/green setup. Which built-in feature provides this?", "options": [{"k": "A", "t": "The ECS deployment circuit breaker with rollback enabled on the service"}, {"k": "B", "t": "A longer health check grace period on the service"}, {"k": "C", "t": "A CloudWatch alarm that emails the team to intervene"}, {"k": "D", "t": "Setting maximumPercent to 200 so more tasks launch during the deployment"}], "answer": ["A"], "multi": false, "explanation": "The ECS deployment circuit breaker detects repeated task launch or health-check failures during a rolling deployment and can automatically roll back to the last stable task set, with no separate blue/green setup. A grace period tolerates failures, an email alarm is manual, and raising maximumPercent does not roll back."},
{"id": "aa:dop-0087", "sources": ["aa:dop-0087"], "q": "A company is building an active/active multi-Region web application and must route users to a healthy Region automatically and keep the application data consistent across Regions with single-digit-millisecond local access. Which TWO services support these goals?", "options": [{"k": "A", "t": "Amazon Route 53 with health checks and latency or failover routing to direct users to a healthy Region"}, {"k": "B", "t": "Amazon DynamoDB global tables for multi-Region active-active data replication"}, {"k": "C", "t": "A single Amazon RDS instance in one Region accessed from both Regions"}, {"k": "D", "t": "Amazon CloudFront with a single origin in one Region only"}, {"k": "E", "t": "Disabling health checks so the routing configuration is simpler"}], "answer": ["A", "B"], "multi": true, "explanation": "Route 53 health checks and routing direct users to a healthy Region, and DynamoDB global tables provide multi-Region active-active replication with low-latency local access. A single-Region RDS instance and a single-origin CloudFront do not provide multi-Region data, and disabling health checks breaks failover."},
{"id": "aa:dop-0088", "sources": ["aa:dop-0088"], "q": "A latency-sensitive TCP-based game backend runs in three Regions. The company wants a static set of entry-point IP addresses that route players over the AWS global network to the nearest healthy regional endpoint, with fast failover if a Region becomes unhealthy. Which service fits?", "options": [{"k": "A", "t": "AWS Global Accelerator, providing static anycast IPs that route over the AWS backbone to the nearest healthy endpoint with fast failover"}, {"k": "B", "t": "Amazon CloudFront, caching the game traffic at edge locations"}, {"k": "C", "t": "A single Elastic IP attached to one Region load balancer"}, {"k": "D", "t": "Latency-based Amazon Route 53 records with a 60-second TTL"}], "answer": ["A"], "multi": false, "explanation": "Global Accelerator provides static anycast IPs and routes TCP/UDP traffic over the AWS backbone to the nearest healthy regional endpoint with fast failover, ideal for a latency-sensitive game backend. CloudFront caches HTTP content, a single Elastic IP is single-Region, and latency-based DNS fails over more slowly and offers no static anycast entry point."},
{"id": "aa:dop-0089", "sources": ["aa:dop-0089"], "q": "An operations team needs memory utilization, disk space, and swap metrics from a fleet of EC2 instances visible in CloudWatch, collected centrally and without writing a custom metric publisher. None of these appear by default. What should they do?", "options": [{"k": "A", "t": "Install and configure the unified CloudWatch agent on the instances to collect and publish memory, disk, and swap metrics to CloudWatch"}, {"k": "B", "t": "Rely on the default EC2 instance metrics, which already include memory and disk usage"}, {"k": "C", "t": "Enable detailed monitoring on the instances to add the memory and disk metrics"}, {"k": "D", "t": "Use VPC Flow Logs to derive memory and disk usage"}], "answer": ["A"], "multi": false, "explanation": "Memory, disk, and swap metrics require the unified CloudWatch agent, which collects and publishes them to CloudWatch with no custom publisher. Default EC2 metrics do not include guest memory or disk, detailed monitoring only increases the frequency of existing metrics, and Flow Logs capture network traffic."},
{"id": "aa:dop-0090", "sources": ["aa:dop-0090"], "q": "Log events arriving in a CloudWatch Logs group must be delivered in near real time to a function that enriches them and to an Amazon OpenSearch Service domain for search, as they arrive. Which feature delivers the matching events to these targets continuously?", "options": [{"k": "A", "t": "CloudWatch Logs subscription filters that stream matching log events to the Lambda function and to OpenSearch (directly or via Kinesis) in near real time"}, {"k": "B", "t": "A daily export task from the log group to Amazon S3"}, {"k": "C", "t": "A scheduled CloudWatch Logs Insights query that runs hourly"}, {"k": "D", "t": "A CloudWatch dashboard that visualizes the log group"}], "answer": ["A"], "multi": false, "explanation": "Subscription filters stream matching log events in near real time to targets such as Lambda, Kinesis, and OpenSearch as they arrive. A daily export and an hourly query are batch or polling, and a dashboard does not deliver events to processors."},
{"id": "aa:dop-0091", "sources": ["aa:dop-0091"], "q": "A company must aggregate high-volume streaming application logs from many sources and reliably load them into Amazon S3, and optionally into Amazon OpenSearch Service, with buffering, optional transformation, and automatic retries, using the least management. Which service fits?", "options": [{"k": "A", "t": "Amazon Data Firehose (Kinesis Data Firehose), a managed delivery stream that buffers, optionally transforms, retries, and loads into S3 and OpenSearch"}, {"k": "B", "t": "Amazon SQS as the delivery mechanism into S3 and OpenSearch"}, {"k": "C", "t": "A fleet of EC2 instances running a custom log shipper to S3 and OpenSearch"}, {"k": "D", "t": "AWS CloudTrail to capture and deliver the application logs"}], "answer": ["A"], "multi": false, "explanation": "Data Firehose is a managed delivery stream that buffers, optionally transforms, retries, and loads streaming data into S3, OpenSearch, and other destinations with minimal management. SQS is a queue rather than a managed loader, a custom EC2 shipper is operationally heavy, and CloudTrail records API activity rather than arbitrary application logs."},
{"id": "aa:dop-0092", "sources": ["aa:dop-0092"], "q": "A team must continuously verify, from outside the application, that a critical user workflow (load the login page, submit credentials, reach the dashboard) succeeds and returns the expected content, and alarm if it breaks, even when no real users are active. Which CloudWatch capability provides this?", "options": [{"k": "A", "t": "CloudWatch Synthetics canaries that run the scripted multi-step workflow on a schedule and alarm on failures"}, {"k": "B", "t": "CloudWatch Logs Insights queries over the application logs"}, {"k": "C", "t": "CloudWatch metric math over existing request metrics"}, {"k": "D", "t": "Real-user monitoring derived from the load balancer access logs"}], "answer": ["A"], "multi": false, "explanation": "Synthetics canaries run scripted, multi-step workflows on a schedule from outside the application, verifying behavior and content and alarming on failures even with no real traffic. Logs Insights and metric math analyze existing data generated by real traffic, and access logs require real users."},
{"id": "aa:dop-0093", "sources": ["aa:dop-0093"], "q": "A metric normal range varies widely by time of day and day of week, so a single static threshold produces frequent false alarms at night and misses anomalies during the day. The team wants alarms based on the expected behavior for the current time. Which CloudWatch capability fits?", "options": [{"k": "A", "t": "CloudWatch anomaly detection, which models expected values per time band and alarms on deviations from the learned band"}, {"k": "B", "t": "A static threshold set to the daytime peak value"}, {"k": "C", "t": "A composite alarm combining several fixed-threshold alarms"}, {"k": "D", "t": "A dashboard annotation that marks the expected ranges"}], "answer": ["A"], "multi": false, "explanation": "Anomaly detection builds a model of expected values that accounts for time-of-day and day-of-week patterns and alarms on deviations from the learned band, reducing false alarms and catching context-specific anomalies. Static and composite fixed thresholds cannot adapt, and a dashboard annotation does not alarm."},
{"id": "aa:dop-0094", "sources": ["aa:dop-0094"], "q": "During an incident, an engineer must interactively search and aggregate millions of structured log events across several CloudWatch Logs groups, computing counts and percentiles by field, without exporting the data or standing up infrastructure. Which tool fits?", "options": [{"k": "A", "t": "CloudWatch Logs Insights, using its query language to search and aggregate across the log groups interactively"}, {"k": "B", "t": "Amazon Athena querying the CloudWatch Logs groups directly"}, {"k": "C", "t": "A CloudWatch Logs metric filter created during the incident"}, {"k": "D", "t": "Exporting the logs to Amazon S3 and loading them into Amazon Redshift"}], "answer": ["A"], "multi": false, "explanation": "Logs Insights provides an interactive query language to search and aggregate large volumes of CloudWatch Logs across groups, computing counts and percentiles by field with no export or infrastructure. Athena and Redshift require the data to be in S3 or loaded first, and a metric filter only affects events going forward."},
{"id": "aa:dop-0095", "sources": ["aa:dop-0095"], "q": "A security team needs one CloudTrail configuration that records management events from every account in the AWS Organization, including accounts created in the future, delivered to a central, access-controlled S3 bucket, without configuring a trail in each account. What should they create?", "options": [{"k": "A", "t": "An organization trail in the management or delegated administrator account, delivering to a central S3 bucket and automatically covering current and future accounts"}, {"k": "B", "t": "A separate trail manually created in each member account, each delivering to its own bucket"}, {"k": "C", "t": "A CloudWatch Logs subscription in each account that forwards events to a central account"}, {"k": "D", "t": "AWS Config enabled in each account to record the management API calls"}], "answer": ["A"], "multi": false, "explanation": "An organization trail records management events for all current and future member accounts and delivers them to a central S3 bucket, with no per-account trail setup. Per-account trails miss future accounts and add effort, subscription forwarding is custom, and AWS Config records configuration rather than API events."},
{"id": "aa:dop-0096", "sources": ["aa:dop-0096"], "q": "After a suspected intrusion, responders must determine which source IP addresses connected to a specific EC2 instance elastic network interface, on which ports, and whether the traffic was accepted or rejected, over the past several hours. Which capability provides this network-level data?", "options": [{"k": "A", "t": "VPC Flow Logs for the instance elastic network interface, capturing source and destination IPs, ports, and accept/reject actions"}, {"k": "B", "t": "The CloudWatch agent collecting system metrics from the instance"}, {"k": "C", "t": "AWS CloudTrail management event history for the account"}, {"k": "D", "t": "Amazon GuardDuty findings only, without any underlying flow records"}], "answer": ["A"], "multi": false, "explanation": "VPC Flow Logs capture IP traffic metadata (source and destination addresses, ports, protocol, and accept/reject) for an ENI, subnet, or VPC, which is exactly the network-level detail the investigation needs. The CloudWatch agent collects system metrics, CloudTrail records API calls rather than packet flows, and GuardDuty findings summarize threats without the raw flow records."},
{"id": "aa:dop-0097", "sources": ["aa:dop-0097"], "q": "A team needs a single CloudWatch alarm that fires when the error rate (errors divided by total requests, as a percentage) exceeds 5% over 5 minutes, using two existing metrics and without publishing a new metric from the application. How should they build it?", "options": [{"k": "A", "t": "Create a metric math expression such as (errors/requests)*100 and configure the alarm to evaluate that expression"}, {"k": "B", "t": "Publish a new custom error-rate metric from the application with PutMetricData and alarm on it"}, {"k": "C", "t": "Create two separate alarms, one on errors and one on requests, and combine them on a dashboard"}, {"k": "D", "t": "Use anomaly detection on the errors metric"}], "answer": ["A"], "multi": false, "explanation": "Metric math computes an expression such as (errors/requests)*100, and an alarm can evaluate that expression directly with no new metric. Publishing a custom metric requires an application change the constraint excludes, two separate alarms do not compute the ratio, and anomaly detection does not enforce a fixed 5% ratio threshold."},
{"id": "aa:dop-0098", "sources": ["aa:dop-0098"], "q": "An EventBridge event bus had an archive configured before a downstream consumer outage. After fixing the consumer, the team must resend only the events from the outage window so they are reprocessed. Which approach accomplishes this?", "options": [{"k": "A", "t": "Start an EventBridge replay of the archive scoped to the outage time window, so the archived events are re-sent to the bus and routed to the targets again"}, {"k": "B", "t": "Read the events from the target SQS dead-letter queue, which holds the full bus history for the window"}, {"k": "C", "t": "Create the archive now and expect it to retroactively contain the outage events"}, {"k": "D", "t": "Re-drive the events from CloudTrail, which stores every EventBridge event payload"}], "answer": ["A"], "multi": false, "explanation": "EventBridge replay re-sends events from an existing archive over a selected time window, and rules route them to targets again. A dead-letter queue holds only failed target deliveries rather than the full bus history, archives are not retroactive, and CloudTrail records API calls rather than event payloads."},
{"id": "aa:dop-0099", "sources": ["aa:dop-0099"], "q": "A team must get EC2 memory utilization metrics and a custom application throughput metric into CloudWatch reliably and at scale, without relying on default instance metrics. Which TWO methods are appropriate?", "options": [{"k": "A", "t": "Install the unified CloudWatch agent to collect and publish memory and other system metrics"}, {"k": "B", "t": "Publish the custom throughput metric using PutMetricData or the CloudWatch embedded metric format (EMF)"}, {"k": "C", "t": "Rely on default EC2 instance metrics, which already include memory utilization"}, {"k": "D", "t": "Write the values only to application log files and never publish them as metrics"}, {"k": "E", "t": "Use AWS Config to record and graph the metrics"}], "answer": ["A", "B"], "multi": true, "explanation": "The unified CloudWatch agent collects guest memory metrics, and custom application metrics are published via PutMetricData or EMF. Default EC2 metrics do not include memory, log-only values are not CloudWatch metrics, and AWS Config records configuration rather than metrics."},
{"id": "aa:dop-0100", "sources": ["aa:dop-0100"], "q": "An organization enabled AWS Systems Manager Incident Manager before November 7, 2025. It wants structured incident management with on-call engagement, escalation, runbooks, and a timeline. Which service provides these capabilities for this existing customer?", "options": [{"k": "A", "t": "AWS Systems Manager Incident Manager"}, {"k": "B", "t": "Amazon SNS alone"}, {"k": "C", "t": "AWS Config"}, {"k": "D", "t": "Amazon Athena"}], "answer": ["A"], "multi": false, "explanation": "Incident Manager provides response plans, on-call schedules, escalation, runbooks, and incident timelines. It stopped accepting new customers on November 7, 2025, but existing enabled customers can continue using it. SNS only sends notifications; Config and Athena do not provide incident coordination."},
{"id": "aa:dop-0101", "sources": ["aa:dop-0101"], "q": "A maintenance Lambda function must run at the start of every hour, with retries on failure and a dead-letter queue for runs that still fail, and the team wants a fully managed scheduler with no servers and no always-on resources. Which approach fits best?", "options": [{"k": "A", "t": "Use Amazon EventBridge Scheduler with an hourly schedule targeting the Lambda, configured with a retry policy and a dead-letter queue"}, {"k": "B", "t": "Run a crontab on an always-on EC2 instance that invokes the Lambda each hour"}, {"k": "C", "t": "Use a Step Functions state machine in a Wait loop that invokes the Lambda every hour"}, {"k": "D", "t": "Have the Lambda set an internal timer that re-invokes itself after sleeping an hour"}], "answer": ["A"], "multi": false, "explanation": "EventBridge Scheduler invokes a target on a cron or rate schedule with no servers, and supports a retry policy and a dead-letter queue for failed invocations. A crontab EC2 instance is an always-on server to manage, a Wait-loop state machine is more complex and costly, and a self-re-invoking Lambda is fragile and not a scheduler."},
{"id": "aa:dop-0102", "sources": ["aa:dop-0102"], "q": "A new hardened AMI must be rolled out to every instance in an Auto Scaling group in controlled batches, keeping a minimum healthy capacity in service, pausing if new instances fail health checks, and with the ability to roll back to the previous launch template version. Which feature does this?", "options": [{"k": "A", "t": "An Auto Scaling group instance refresh using the new launch template version, with a minimum healthy percentage and rollback on failure"}, {"k": "B", "t": "Manually terminating instances in batches and letting the group relaunch them"}, {"k": "C", "t": "Increasing the desired capacity so new-AMI instances are added alongside the old ones, then reducing it"}, {"k": "D", "t": "Editing each instance in place over SSH to apply the hardening"}], "answer": ["A"], "multi": false, "explanation": "Instance refresh replaces instances in batches using the updated launch template, honors a minimum healthy percentage, pauses on health-check failures, and can roll back to the previous version. Manual termination lacks built-in gating and rollback, scaling up then down mixes versions without controlled replacement, and in-place SSH edits are not immutable or repeatable."},
{"id": "aa:dop-0103", "sources": ["aa:dop-0103"], "q": "An automated remediation workflow has many steps with conditional branches, a wait for an external approval, retries with backoff, and per-step error handling, and the team needs the execution history and current state to be visible and auditable. Which service best orchestrates it?", "options": [{"k": "A", "t": "An AWS Step Functions state machine, which models branches, waits, retries with backoff, and error handling with a visual execution history"}, {"k": "B", "t": "A single AWS Lambda function containing the whole workflow with nested try/catch blocks and sleeps"}, {"k": "C", "t": "A chain of EventBridge rules invoking Lambda functions with no central state"}, {"k": "D", "t": "An SSM Run Command document executed once per step manually"}], "answer": ["A"], "multi": false, "explanation": "Step Functions orchestrate multi-step workflows with branching, waits, retries with backoff, and per-step error handling, and provide a visual, auditable execution history. A monolithic Lambda is opaque and bounded by the function timeout, chained EventBridge rules lack central state, and manual Run Command steps are not orchestration."},
{"id": "aa:dop-0104", "sources": ["aa:dop-0104"], "q": "A team must automatically react to AWS-reported operational events that affect their own resources, such as scheduled EC2 maintenance, an EBS volume needing attention, or a Regional service issue, by opening a ticket and notifying on-call. Which event source should their EventBridge rule match?", "options": [{"k": "A", "t": "AWS Health events (AWS Health Dashboard / Health API) delivered to EventBridge, including account-specific and public service events"}, {"k": "B", "t": "A scheduled job that scrapes the public AWS status page for issues"}, {"k": "C", "t": "CloudTrail management events for the affected services"}, {"k": "D", "t": "CloudWatch billing alarms tied to the affected services"}], "answer": ["A"], "multi": false, "explanation": "AWS Health publishes account-specific and public operational events to EventBridge, so a rule can open tickets and notify on-call automatically. Scraping the status page is unreliable and not account-specific, CloudTrail records API calls, and billing alarms are about cost."},
{"id": "aa:dop-0105", "sources": ["aa:dop-0105"], "q": "During an incident, the team must run an emergency mitigation command on several hundred EC2 instances at once, capture each instance output centrally, target the instances by tag, and do so without opening SSH or managing bastion hosts and keys. Which capability fits?", "options": [{"k": "A", "t": "AWS Systems Manager Run Command, targeting instances by tag, executing at scale and capturing output centrally without SSH"}, {"k": "B", "t": "Open SSH from a bastion host and script a loop over the instance IP addresses"}, {"k": "C", "t": "Trigger an Auto Scaling instance refresh to roll out the mitigation in a new AMI"}, {"k": "D", "t": "Use the EC2 Serial Console on each instance to run the command"}], "answer": ["A"], "multi": false, "explanation": "Run Command executes commands across many managed instances selected by tag, captures output centrally, and needs no SSH, bastions, or keys, making it ideal for emergency mitigation at scale. A bastion SSH loop requires key and bastion management and is slow, an instance refresh is not an immediate command, and the serial console is per-instance."},
{"id": "aa:dop-0106", "sources": ["aa:dop-0106"], "q": "An asynchronously invoked Lambda function must route the records of successful invocations to one downstream target and the records of invocations that fail after retries to a different target for investigation, without adding error-handling code inside the function. Which feature provides this?", "options": [{"k": "A", "t": "Lambda destinations, configuring an on-success destination and an on-failure destination for asynchronous invocations (for example SQS, SNS, or EventBridge)"}, {"k": "B", "t": "A Lambda dead-letter queue, which captures both successful and failed invocation records"}, {"k": "C", "t": "An EventBridge rule that inspects the function CloudWatch Logs for success and failure"}, {"k": "D", "t": "Try/catch logic in the function that writes outcomes to two separate SQS queues"}], "answer": ["A"], "multi": false, "explanation": "Lambda destinations route asynchronous invocation results to separate on-success and on-failure targets (SQS, SNS, EventBridge, or another function) with no in-function error-handling code. A dead-letter queue captures only failures, log parsing is custom, and in-function try/catch is exactly the code the requirement excludes."},
{"id": "aa:dop-0107", "sources": ["aa:dop-0107"], "q": "When an S3 bucket is created or modified without default encryption, it must be automatically brought into compliance across all accounts in the Organization, with no human action. Which TWO components together implement this?", "options": [{"k": "A", "t": "An AWS Config rule such as s3-bucket-server-side-encryption-enabled that detects the noncompliant bucket, deployed organization-wide"}, {"k": "B", "t": "An automatic remediation action on the rule that runs an SSM Automation document to enable default encryption"}, {"k": "C", "t": "A nightly Amazon Athena query over CloudTrail that lists unencrypted buckets for an engineer to fix"}, {"k": "D", "t": "An SCP that denies s3:CreateBucket entirely"}, {"k": "E", "t": "A CloudWatch dashboard that displays each bucket encryption status"}], "answer": ["A", "B"], "multi": true, "explanation": "A Config rule detects buckets that lack default encryption (deployable organization-wide via a conformance pack), and an associated SSM Automation remediation enables encryption automatically. A nightly query is manual, a blanket SCP deny blocks all buckets without remediating, and a dashboard only visualizes."},
{"id": "aa:dop-0108", "sources": ["aa:dop-0108"], "q": "A central security account must receive specific findings and resource-change events from dozens of member accounts and act on them with rules, while member accounts continue to own their own event buses. Which EventBridge configuration enables this with the least custom code?", "options": [{"k": "A", "t": "In each member account, add an EventBridge rule that forwards the selected events to a custom event bus in the central account, and grant that central bus a resource policy allowing those accounts to put events"}, {"k": "B", "t": "Have each member account write the events to an S3 bucket that the central account reads hourly"}, {"k": "C", "t": "Give the central account cross-account IAM roles and have it poll each member account event bus"}, {"k": "D", "t": "Disable the default bus in member accounts and share a single global event bus across all accounts"}], "answer": ["A"], "multi": false, "explanation": "EventBridge supports cross-account delivery: member-account rules forward selected events to a central custom bus whose resource policy permits those accounts to put events, where central rules act on them, with no custom code. S3 batching and polling are custom and not near real time, and event buses cannot be shared globally that way."},
{"id": "aa:dop-0109", "sources": ["aa:dop-0109"], "q": "When p95 request latency on a service exceeds a threshold for several minutes, the EC2 fleet should automatically add capacity in proportion to how far latency exceeds the target, and scale back as it recovers, with no manual action. Which configuration achieves this?", "options": [{"k": "A", "t": "A CloudWatch alarm on the p95 latency metric tied to an Auto Scaling step (or target tracking) scaling policy that adds capacity based on the breach magnitude"}, {"k": "B", "t": "A CloudWatch alarm that emails on-call to add instances manually"}, {"k": "C", "t": "A scheduled scaling action that adds capacity at fixed times of day"}, {"k": "D", "t": "A fixed, over-provisioned group sized for worst-case latency at all times"}], "answer": ["A"], "multi": false, "explanation": "A CloudWatch alarm on p95 latency linked to a step or target tracking scaling policy adds capacity automatically in proportion to the breach and scales back on recovery. Emailing on-call is manual, scheduled scaling is not latency-responsive, and fixed over-provisioning is costly and static."},
{"id": "aa:dop-0110", "sources": ["aa:dop-0110"], "q": "Compliance requires that the key material backing a customer-managed KMS key be rotated on a yearly schedule with no application changes, no re-encryption of existing data, and no change to references to the key. Which approach meets this?", "options": [{"k": "A", "t": "Enable automatic key rotation on the customer-managed KMS key, which rotates the backing key material on a schedule while the key ID and ARN remain the same"}, {"k": "B", "t": "Create a new KMS key each year, re-encrypt all existing data with it, and update every reference to the new key ARN"}, {"k": "C", "t": "Rotate the IAM access keys of the principals that use the KMS key each year"}, {"k": "D", "t": "Schedule a Lambda function to call GenerateDataKey daily to rotate the key"}], "answer": ["A"], "multi": false, "explanation": "KMS automatic key rotation rotates the backing key material on a schedule (default annually) while the key ID and ARN stay the same, so no application changes or re-encryption are needed. Creating a new key forces re-encryption and reference changes, rotating IAM access keys is unrelated to KMS key material, and generating data keys does not rotate the customer master key."},
{"id": "aa:dop-0111", "sources": ["aa:dop-0111"], "q": "A security team must continuously identify which IAM roles, S3 buckets, KMS keys, and SQS queues across the Organization grant access to external accounts or the public, and review newly created external access from one centralized view. Which service is designed for this?", "options": [{"k": "A", "t": "AWS IAM Access Analyzer external access analysis, with a delegated administrator and the organization as the zone of trust"}, {"k": "B", "t": "Amazon Inspector scanning the resources for misconfigurations"}, {"k": "C", "t": "AWS Config rules that check each resource policy individually with no central analyzer"}, {"k": "D", "t": "Amazon Macie classifying the data stored in the resources"}], "answer": ["A"], "multi": false, "explanation": "IAM Access Analyzer analyzes resource-based policies to identify access granted to external principals or the public, supports an organization zone of trust with a delegated administrator, and continuously surfaces new findings. Inspector scans vulnerabilities, Config rules are not the purpose-built external-access analyzer, and Macie classifies data."},
{"id": "aa:dop-0112", "sources": ["aa:dop-0112"], "q": "An organization must guarantee that no S3 bucket in any member account can be made public through ACLs or bucket policies, that the control cannot be turned off by account administrators, and that it applies to new accounts automatically. Which combination meets this?", "options": [{"k": "A", "t": "Enable account-level S3 Block Public Access in each account and add an SCP that denies disabling Block Public Access (for example s3:PutAccountPublicAccessBlock), applied organization-wide"}, {"k": "B", "t": "Enable account-level S3 Block Public Access only, trusting administrators not to disable it"}, {"k": "C", "t": "Create an AWS Config rule that detects public buckets and emails the team"}, {"k": "D", "t": "Tag all buckets as private and rely on the tag to keep them private"}], "answer": ["A"], "multi": false, "explanation": "Account-level Block Public Access overrides ACLs and policies, and an SCP denying the action that disables it prevents administrators from turning it off, applied organization-wide including new accounts. Block Public Access alone can be disabled by an administrator, a Config rule only detects, and tags do not enforce access."},
{"id": "aa:dop-0113", "sources": ["aa:dop-0113"], "q": "A private S3 bucket must be accessible only from a specific VPC, and the restriction must hold even for IAM principals that have broad S3 permissions granted elsewhere. Which configuration enforces VPC-only access?", "options": [{"k": "A", "t": "Create an S3 gateway VPC endpoint and add a bucket policy with an explicit Deny when aws:SourceVpc does not equal the VPC ID"}, {"k": "B", "t": "Add a bucket policy with a conditional Allow only for the VPC and rely on the default implicit deny"}, {"k": "C", "t": "Attach a security group to the bucket that allows only the VPC CIDR range"}, {"k": "D", "t": "Use a network ACL on the subnet to limit access to the bucket"}], "answer": ["A"], "multi": false, "explanation": "Only an explicit Deny when aws:SourceVpc does not match overrides any Allow from IAM or elsewhere, and an S3 gateway endpoint supplies the aws:SourceVpc context. A conditional Allow does not restrict other Allows, and security groups and network ACLs do not control access to S3."},
{"id": "aa:dop-0114", "sources": ["aa:dop-0114"], "q": "Auditors require cryptographic proof that delivered CloudTrail log files were not modified or deleted after delivery, and the ability to validate that independently later. Which approach provides this assurance?", "options": [{"k": "A", "t": "Enable CloudTrail log file integrity validation, which produces signed digest files, and store the logs and digests in a versioned, Object Lock-protected S3 bucket"}, {"k": "B", "t": "Enable S3 server access logging on the trail bucket"}, {"k": "C", "t": "Encrypt the log files with SSE-KMS only"}, {"k": "D", "t": "Send the logs to CloudWatch Logs and rely on the log group retention period"}], "answer": ["A"], "multi": false, "explanation": "CloudTrail log file integrity validation produces signed digest files you can validate independently to prove logs were not altered or deleted, and storing logs and digests with versioning and Object Lock further protects them. Access logging records requests, encryption provides confidentiality rather than tamper-evidence, and retention is not integrity validation."},
{"id": "aa:dop-0115", "sources": ["aa:dop-0115"], "q": "A company must continuously discover and classify sensitive data (PII, credentials, financial data) stored across thousands of S3 buckets in many accounts, and report buckets that are unencrypted or publicly accessible, with the least custom development. Which service is purpose-built for this?", "options": [{"k": "A", "t": "Amazon Macie with the organization integration, which discovers and classifies sensitive S3 data and reports bucket security posture"}, {"k": "B", "t": "Amazon Inspector scanning the buckets for sensitive data"}, {"k": "C", "t": "AWS Config rules that read object contents to find sensitive data"}, {"k": "D", "t": "A custom Lambda fleet that downloads and scans every object with regular expressions"}], "answer": ["A"], "multi": false, "explanation": "Macie uses managed machine learning to discover and classify sensitive data in S3 across accounts and reports bucket encryption and public-access posture, with no custom development. Inspector scans vulnerabilities, Config evaluates configuration rather than object contents, and a custom Lambda fleet is heavy to build and operate."},
{"id": "aa:dop-0116", "sources": ["aa:dop-0116"], "q": "A team needs continuous, automatic vulnerability assessment of EC2 instances, container images in Amazon ECR, and Lambda functions for known CVEs, prioritized by severity and sent to a central security view, without scheduling scans manually. Which service provides this?", "options": [{"k": "A", "t": "Amazon Inspector, which continuously scans EC2, ECR images, and Lambda for CVEs and sends prioritized findings to Security Hub"}, {"k": "B", "t": "Amazon Macie scanning the workloads for vulnerabilities"}, {"k": "C", "t": "AWS Config rules evaluating installed package versions on each resource"}, {"k": "D", "t": "A scheduled CodeBuild job that runs a scanner the team maintains for every resource type"}], "answer": ["A"], "multi": false, "explanation": "Amazon Inspector continuously and automatically scans EC2, ECR container images, and Lambda functions for known CVEs, prioritizes by severity, and integrates with Security Hub. Macie classifies sensitive data, AWS Config evaluates configuration rather than CVEs, and a custom CodeBuild scanner is not a managed continuous vulnerability service."},
{"id": "aa:dop-0117", "sources": ["aa:dop-0117"], "q": "A central compliance team needs one view of AWS Config rule compliance and resource configurations from every account and Region in the Organization, updated as new accounts join, without logging into each account. Which feature provides this?", "options": [{"k": "A", "t": "An AWS Config aggregator authorized for the Organization, collecting configuration and compliance data from all accounts and Regions into one account"}, {"k": "B", "t": "Enabling AWS Config in each account and reviewing each account console separately"}, {"k": "C", "t": "A CloudWatch cross-account dashboard of AWS Config metrics"}, {"k": "D", "t": "An S3 bucket where each account delivers its Config snapshots, queried manually"}], "answer": ["A"], "multi": false, "explanation": "An organization Config aggregator collects configuration and compliance data across all accounts and Regions into a single view and includes new accounts automatically. Per-account review is manual, a metrics dashboard is not the aggregated compliance data, and manually querying delivered snapshots is custom."},
{"id": "aa:dop-0118", "sources": ["aa:dop-0118"], "q": "A platform team must enforce least privilege at scale: cap the maximum permissions available to every account in the Organization, and ensure that roles application teams create can never exceed an approved permission set. Which TWO controls map to these two needs?", "options": [{"k": "A", "t": "Service Control Policies attached to OUs to cap the maximum permissions for accounts in the Organization"}, {"k": "B", "t": "Required IAM permissions boundaries on the roles application teams are allowed to create, capping those roles effective permissions"}, {"k": "C", "t": "Resource-based policies on every S3 bucket as the primary least-privilege control"}, {"k": "D", "t": "An IAM group with an administrator policy shared by all teams"}, {"k": "E", "t": "Access keys rotated weekly for all principals"}], "answer": ["A", "B"], "multi": true, "explanation": "SCPs cap what an entire account or OU can do, and permissions boundaries cap what a created identity can do, together enforcing least privilege at scale. Resource-based policies are per-resource, a shared administrator group grants broad access, and key rotation does not constrain permissions."},
{"id": "aa:dop-0119", "sources": ["aa:dop-0119"], "q": "A workload in account A must call services in account B continuously, following best practice by using only short-lived credentials and letting account B revoke or change the access centrally. Which mechanism should be used?", "options": [{"k": "A", "t": "Create an IAM role in account B that trusts account A, and have the account A workload assume it with sts:AssumeRole to obtain temporary credentials"}, {"k": "B", "t": "Create an IAM user in account B and store its long-term access keys in the account A workload"}, {"k": "C", "t": "Share the account B root user credentials with the account A workload"}, {"k": "D", "t": "Make the account B resources public so account A can use them without credentials"}], "answer": ["A"], "multi": false, "explanation": "A cross-account role that account B owns and account A assumes issues short-lived credentials and lets account B revoke or change the trust centrally, following best practice. Long-term user keys, root credentials, and public resources are insecure."},
{"id": "aa:dop-0120", "sources": ["aa:dop-0120"], "q": "A public web application behind an Application Load Balancer needs TLS certificates that are issued, deployed, and automatically renewed before expiry, with no manual rotation, no risk of an expired-certificate outage, and no additional certificate cost. Which approach fits?", "options": [{"k": "A", "t": "Use AWS Certificate Manager to provision public certificates and attach them to the ALB; ACM renews them automatically before expiry"}, {"k": "B", "t": "Buy certificates from a third party, upload them to the ALB, and renew them manually each year"}, {"k": "C", "t": "Generate self-signed certificates and install them on the ALB"}, {"k": "D", "t": "Terminate TLS on the EC2 instances using certificates baked into the AMI"}], "answer": ["A"], "multi": false, "explanation": "ACM provisions public certificates at no additional certificate cost, attaches them to the ALB, and automatically renews them before expiry, removing manual rotation and expiry outages. Third-party uploads require manual renewal, self-signed certificates are untrusted by browsers, and AMI-baked certificates require manual rotation and rebuilds."},
{"id": "aa:dop-0121", "sources": ["aa:dop-0121"], "q": "A public web application behind CloudFront and an ALB is receiving SQL injection and cross-site scripting attempts and credential-stuffing bursts from specific IP ranges. The team wants to filter these Layer 7 attacks using managed rules and rate limiting, with minimal custom code. Which service should they add?", "options": [{"k": "A", "t": "AWS WAF with AWS Managed Rules (including SQL injection and XSS rule groups) and a rate-based rule, associated with the CloudFront distribution or the ALB"}, {"k": "B", "t": "AWS Shield Standard, which already blocks application-layer SQL injection and XSS"}, {"k": "C", "t": "Security group rules that block the malicious request patterns"}, {"k": "D", "t": "Network ACLs that inspect the HTTP request bodies"}], "answer": ["A"], "multi": false, "explanation": "AWS WAF inspects and filters Layer 7 HTTP requests using managed rule groups (SQL injection, XSS) and rate-based rules and attaches to CloudFront or the ALB, with minimal custom code. Shield Standard addresses DDoS, and security groups and network ACLs operate at the network and transport layers and cannot inspect HTTP content."},
{"id": "aa:dop-0122", "sources": ["aa:dop-0122"], "q": "An organization must standardize required tag keys and allowed values across all accounts, report resources that do not comply with the standard, and prevent noncompliant tag values on supported resources. Which Organizations feature provides this governance?", "options": [{"k": "A", "t": "Tag policies in AWS Organizations, which define standardized tag keys and values, report noncompliance, and can enforce compliant values on supported resources"}, {"k": "B", "t": "An AWS Config rule that emails when tags are missing, with no central organization standard"}, {"k": "C", "t": "A Lambda function triggered on resource creation that overwrites tags"}, {"k": "D", "t": "A spreadsheet of required tags shared with account owners"}], "answer": ["A"], "multi": false, "explanation": "Tag policies define standardized tag keys and allowed values across the Organization, report noncompliant resources, and can enforce compliant tagging on supported resources. A Config rule is detective and not the organization tag standard, a custom Lambda is partial, and a spreadsheet is manual."},
{"id": "aa:dop-0123", "sources": ["aa:dop-0123"], "q": "A security team must be alerted in near real time, organization-wide, whenever the root user of any account signs in or performs an action, and route the alert to an incident channel. Which design accomplishes this with the least custom code?", "options": [{"k": "A", "t": "Use an organization CloudTrail and, in a delegated security account, an EventBridge rule that matches root-user events and targets an SNS topic that notifies the incident channel"}, {"k": "B", "t": "In each account, manually review CloudTrail Event history every week for root usage"}, {"k": "C", "t": "Disable the root user in every account so the event cannot occur"}, {"k": "D", "t": "Create a per-account CloudWatch dashboard that charts sign-in counts"}], "answer": ["A"], "multi": false, "explanation": "An organization CloudTrail plus an EventBridge rule matching root-user events in a delegated security account can notify an incident channel via SNS in near real time, organization-wide, with no custom code. Weekly manual review is not timely, the root user cannot be disabled, and a dashboard does not alert."},
{"id": "aa:dop-0124", "sources": ["aa:dop-0124"], "q": "Database credentials must be rotated automatically on a schedule and encrypted at rest with a specific compliance-approved customer-managed KMS key, and an application running on Amazon ECS must retrieve them at runtime. Which TWO configuration steps meet the requirements?", "options": [{"k": "A", "t": "Store the credentials in AWS Secrets Manager and enable scheduled rotation with the database rotation function"}, {"k": "B", "t": "Configure the secret to use the approved customer-managed KMS key and grant the ECS task role both secretsmanager:GetSecretValue and kms:Decrypt on that key"}, {"k": "C", "t": "Store the credentials in Parameter Store as a String parameter and rotate them with a custom cron job"}, {"k": "D", "t": "Use the default Secrets Manager AWS managed key to avoid managing a key"}, {"k": "E", "t": "Embed the credentials in the ECS task definition environment variables for fast access"}], "answer": ["A", "B"], "multi": true, "explanation": "Secrets Manager provides scheduled rotation via the database rotation function, and configuring the secret to use the approved customer-managed KMS key with the task role granted GetSecretValue and kms:Decrypt satisfies the encryption and runtime-retrieval requirements. A Parameter Store String has no native rotation or encryption, the default managed key does not meet the customer-managed-key requirement, and task-definition environment variables are insecure and unrotated."},
{"id": "aa:dop-0125", "sources": ["aa:dop-0125"], "q": "A production pipeline receives several commits while a long deployment is running. Every commit must be deployed exactly once and in arrival order; newer executions must never overtake older ones. Which CodePipeline configuration meets the requirement?", "options": [{"k": "A", "t": "Use a V2 pipeline with QUEUED execution mode"}, {"k": "B", "t": "Use the default SUPERSEDED execution mode"}, {"k": "C", "t": "Use PARALLEL execution mode and enable stage rollback"}, {"k": "D", "t": "Create an EventBridge rule that cancels every older execution"}], "answer": ["A"], "multi": false, "explanation": "QUEUED mode processes executions one at a time in the order they reach each locked stage and requires a V2 pipeline. SUPERSEDED allows newer executions to overtake older ones. PARALLEL runs independently and does not support stage rollback."},
{"id": "aa:dop-0126", "sources": ["aa:dop-0126"], "q": "A platform team must produce hardened AMIs every week, run automated component tests, and make approved images available in two Regions and several accounts. Which THREE EC2 Image Builder elements implement this?", "options": [{"k": "A", "t": "An image recipe and components that install the hardening configuration"}, {"k": "B", "t": "Build and test workflows in a scheduled image pipeline"}, {"k": "C", "t": "Distribution settings for the destination Regions and accounts"}, {"k": "D", "t": "A manual AMI copy performed by each application team"}, {"k": "E", "t": "An EC2 user data script that mutates every instance after launch instead of baking an image"}], "answer": ["A", "B", "C"], "multi": true, "explanation": "Image Builder recipes/components define the image, pipeline workflows build and test it on a schedule, and distribution settings copy or share the resulting AMI to target Regions and accounts. Manual copies and post-launch mutation do not provide a centrally tested immutable artifact pipeline."},
{"id": "aa:dop-0127", "sources": ["aa:dop-0127"], "q": "An EC2 application needs a manually controlled blue/green release that shifts traffic gradually while both environments use the same unchanged database schema. Which THREE actions meet the requirement?", "options": [{"k": "A", "t": "Create a green Auto Scaling group behind a separate Application Load Balancer"}, {"k": "B", "t": "Create weighted Route 53 alias records for the blue and green load balancers"}, {"k": "C", "t": "Configure both application environments to use the same RDS primary endpoint"}, {"k": "D", "t": "Send the green environment to the unreadable Multi-AZ standby instance"}, {"k": "E", "t": "Use Route 53 failover routing to shift 10% increments"}], "answer": ["A", "B", "C"], "multi": true, "explanation": "Separate load balancers provide two routable environments, weighted aliases support gradual traffic shifts, and a shared primary database keeps writes consistent when no schema split is required. An RDS Multi-AZ standby is not a read/write endpoint, and failover routing is active/passive rather than percentage-based."},
{"id": "aa:dop-0128", "sources": ["aa:dop-0128"], "q": "A legacy API and five replacement Lambda handlers must be canary-tested through the existing Application Load Balancer. Each handler owns a different URL path, only a small share of requests should reach Lambda, and the existing ALB access-log format must remain unchanged. What should the engineer do?", "options": [{"k": "A", "t": "Create one Lambda target group per function and path-based listener rules that forward with weights between each Lambda target group and the existing instance target group"}, {"k": "B", "t": "Register all five Lambda functions in one target group and weight individual functions"}, {"k": "C", "t": "Create a second ALB and use weighted Route 53 records"}, {"k": "D", "t": "Put the Lambda functions behind API Gateway and replace the public DNS record immediately"}], "answer": ["A"], "multi": false, "explanation": "An ALB Lambda target group can register one function. Path rules can use weighted forwarding between the existing instance target group and the Lambda target group for that endpoint. Reusing the ALB preserves its access-log stream; a second ALB would create a different load balancer ID and log stream."},
{"id": "aa:dop-0129", "sources": ["aa:dop-0129"], "q": "A production deployment action succeeds, but the pipeline must observe a bake period and roll the stage back to its previous successful execution if a CloudWatch 5xx alarm enters ALARM. What should be configured?", "options": [{"k": "A", "t": "Add an On Success stage condition with a CloudWatchAlarm rule and a Rollback result"}, {"k": "B", "t": "Add an Entry condition with a Skip result after the deployment has completed"}, {"k": "C", "t": "Run the pipeline in PARALLEL mode and rely on automatic stage rollback"}, {"k": "D", "t": "Add a manual approval action that automatically evaluates the alarm"}], "answer": ["A"], "multi": false, "explanation": "An On Success condition is evaluated after the stage succeeds and can use a CloudWatch alarm rule with Rollback as the result, covering a post-deployment bake period. Entry conditions run before a stage, manual approvals do not evaluate alarms automatically, and PARALLEL mode does not support stage rollback."},
{"id": "aa:dop-0130", "sources": ["aa:dop-0130"], "q": "A company must vend governed AWS accounts to teams and automatically deploy a logging and security baseline whenever an account joins a targeted OU. Which TWO services or features provide the native control plane?", "options": [{"k": "A", "t": "AWS Control Tower Account Factory for governed account provisioning"}, {"k": "B", "t": "CloudFormation StackSets with service-managed permissions and automatic OU deployment"}, {"k": "C", "t": "Manual root-user setup in every new account"}, {"k": "D", "t": "VPC peering from the management account to every member account"}, {"k": "E", "t": "Cross-account CloudFormation exports with Fn::ImportValue"}], "answer": ["A", "B"], "multi": true, "explanation": "Control Tower Account Factory standardizes governed account creation. Service-managed StackSets can target OUs and automatically create stack instances as accounts join. Manual setup, peering, and cross-account exports do not provide account vending plus lifecycle deployment."},
{"id": "aa:dop-0131", "sources": ["aa:dop-0131"], "q": "A CloudFormation template must pass a database password to an RDS resource without storing the plaintext value in the template or resolving it before deployment. Which mechanism should be used?", "options": [{"k": "A", "t": "A Secrets Manager dynamic reference in the resource property"}, {"k": "B", "t": "A plaintext parameter with the password committed to source control"}, {"k": "C", "t": "A Mappings section containing environment passwords"}, {"k": "D", "t": "A stack output that exports the plaintext password"}], "answer": ["A"], "multi": false, "explanation": "A Secrets Manager dynamic reference lets CloudFormation retrieve the secret only when provisioning the resource and avoids embedding the resolved value in the template. Plaintext parameters, mappings, and outputs expose the credential."},
{"id": "aa:dop-0132", "sources": ["aa:dop-0132"], "q": "A security team needs one patch configuration for selected OUs across multiple accounts and Regions, with separate scan and install schedules and centralized compliance. What is the recommended Systems Manager approach?", "options": [{"k": "A", "t": "Create a Patch Manager patch policy in Systems Manager Quick Setup and target the OUs and Regions"}, {"k": "B", "t": "Create an independent crontab on every EC2 instance"}, {"k": "C", "t": "Use a Quick Setup Host Management configuration, which installs all missing patches"}, {"k": "D", "t": "Run CodeBuild over SSH against every instance"}], "answer": ["A"], "multi": false, "explanation": "A Quick Setup patch policy is the recommended organization-scale method and supports target OUs, Regions, baselines, scan schedules, install schedules, and compliance. Host Management Quick Setup can scan but does not install patches; cron and SSH do not provide reliable centralized governance."},
{"id": "aa:dop-0133", "sources": ["aa:dop-0133"], "q": "A production feature flag must be syntactically validated, deployed gradually, and rolled back automatically if application errors rise. Which THREE AWS AppConfig controls meet the requirements?", "options": [{"k": "A", "t": "Attach a JSON Schema or Lambda validator to the configuration profile"}, {"k": "B", "t": "Use a canary or linear deployment strategy with a bake time"}, {"k": "C", "t": "Associate a CloudWatch alarm and the IAM role AppConfig uses to monitor it"}, {"k": "D", "t": "Deploy the value directly as an unvalidated Lambda environment variable"}, {"k": "E", "t": "Disable alarm actions during the deployment"}], "answer": ["A", "B", "C"], "multi": true, "explanation": "Validators reject malformed configuration before deployment. A canary or linear strategy limits initial exposure and includes monitoring time. AppConfig can monitor associated CloudWatch alarms and automatically roll back; disabled alarm actions prevent that rollback behavior."},
{"id": "aa:dop-0134", "sources": ["aa:dop-0134"], "q": "An S3 bucket already contains 40 million objects. The company now enables Cross-Region Replication and requires both the existing objects and all future writes to appear in the destination bucket. Which TWO actions are required?", "options": [{"k": "A", "t": "Configure live Cross-Region Replication for new and updated objects"}, {"k": "B", "t": "Run an S3 Batch Replication job for objects that predate the replication rule"}, {"k": "C", "t": "Wait for live replication to copy the existing objects automatically"}, {"k": "D", "t": "Use an S3 lifecycle transition to copy the objects to another Region"}, {"k": "E", "t": "Enable Transfer Acceleration on the destination bucket"}], "answer": ["A", "B"], "multi": true, "explanation": "Live replication applies to eligible new or updated objects after the rule is configured. It is not retroactive, so S3 Batch Replication is required for preexisting objects. Lifecycle transitions change storage class; Transfer Acceleration does not replicate data."},
{"id": "aa:dop-0135", "sources": ["aa:dop-0135"], "q": "A static application must use one public hostname, serve from regional S3 origins, and fail over without custom edge code. Which THREE components provide the most operationally efficient design?", "options": [{"k": "A", "t": "CloudFormation StackSets to deploy the regional S3 infrastructure consistently"}, {"k": "B", "t": "S3 replication to keep the regional origins populated"}, {"k": "C", "t": "A CloudFront distribution with an origin group, plus a Route 53 alias to the distribution"}, {"k": "D", "t": "A Lambda@Edge function that reimplements origin health checks and routing"}, {"k": "E", "t": "Separate simple Route 53 records that expose each bucket hostname directly"}], "answer": ["A", "B", "C"], "multi": true, "explanation": "StackSets standardizes multi-Region infrastructure, S3 replication maintains regional copies, and CloudFront origin groups provide native origin failover behind one distribution. Route 53 aliases the friendly name to that distribution. Custom edge routing is unnecessary."},
{"id": "aa:dop-0136", "sources": ["aa:dop-0136"], "q": "A team will run an AWS Fault Injection Service experiment against production. The experiment must stop immediately if checkout error rate exceeds the approved steady-state threshold. What should be configured in the experiment template?", "options": [{"k": "A", "t": "A stop condition that references a CloudWatch alarm on checkout error rate"}, {"k": "B", "t": "An SNS subscription with no CloudWatch alarm"}, {"k": "C", "t": "A CloudFormation deletion policy"}, {"k": "D", "t": "An EventBridge archive replay"}], "answer": ["A"], "multi": false, "explanation": "FIS stop conditions reference CloudWatch alarms. If the alarm enters ALARM during the experiment, FIS stops the experiment and it cannot be resumed. Notifications alone and unrelated CloudFormation or EventBridge features do not enforce the safety threshold."},
{"id": "aa:dop-0137", "sources": ["aa:dop-0137"], "q": "An SQS consumer occasionally receives poison messages, and normal messages can be delivered more than once. Which TWO design choices make the workload resilient?", "options": [{"k": "A", "t": "Configure a redrive policy to move repeatedly failing messages to a dead-letter queue"}, {"k": "B", "t": "Make message processing idempotent so duplicate delivery does not corrupt state"}, {"k": "C", "t": "Set the visibility timeout to zero for all messages"}, {"k": "D", "t": "Delete each message before processing begins"}, {"k": "E", "t": "Replace the queue with a periodic EC2 polling script and no retry controls"}], "answer": ["A", "B"], "multi": true, "explanation": "A DLQ isolates messages that exceed the maximum receive count, while idempotency handles SQS at-least-once delivery safely. Zero visibility and preemptive deletion increase duplication or data loss."},
{"id": "aa:dop-0138", "sources": ["aa:dop-0138"], "q": "A monitoring account must query metrics, logs, and traces from dozens of source accounts in the same Region without copying all telemetry into custom buckets. Which TWO CloudWatch cross-account observability resources are required?", "options": [{"k": "A", "t": "An observability access manager sink in the monitoring account"}, {"k": "B", "t": "A link from each source account to the monitoring account sink"}, {"k": "C", "t": "A VPC peering connection for every account pair"}, {"k": "D", "t": "An organization trail that converts metrics into CloudTrail events"}, {"k": "E", "t": "Public read access to every log group"}], "answer": ["A", "B"], "multi": true, "explanation": "CloudWatch cross-account observability uses an OAM sink in the monitoring account and links from source accounts. It shares supported telemetry through the service control plane; VPC peering, CloudTrail conversion, and public logs are unnecessary or insecure."},
{"id": "aa:dop-0139", "sources": ["aa:dop-0139"], "q": "A closed-source service on one EC2 instance leaks memory and must be restarted before memory utilization reaches 90%. The CloudWatch agent already publishes memory utilization as a metric. Which TWO actions provide the most operationally efficient automatic recovery?", "options": [{"k": "A", "t": "Create a CloudWatch alarm directly on the agent-published memory metric and notify an SNS topic"}, {"k": "B", "t": "Subscribe a Lambda function that starts an SSM Run Command restart document to the SNS topic"}, {"k": "C", "t": "Create a log metric filter for a metric that already exists"}, {"k": "D", "t": "Subscribe the EC2 instance itself directly to the SNS topic"}, {"k": "E", "t": "Use an EventBridge scheduled rule to check memory once per day"}], "answer": ["A", "B"], "multi": true, "explanation": "The agent already publishes a CloudWatch metric, so the alarm can use it directly. SNS can invoke Lambda, and Lambda can call Systems Manager Run Command to restart the service without SSH. A duplicate metric filter is unnecessary, and EC2 instances are not SNS subscribers."},
{"id": "aa:dop-0140", "sources": ["aa:dop-0140"], "q": "A company must continuously stream selected CloudWatch metrics to a third-party observability platform through Amazon Data Firehose with low latency and no polling. Which feature should it configure?", "options": [{"k": "A", "t": "A CloudWatch metric stream with the Firehose delivery stream as the destination"}, {"k": "B", "t": "A CloudWatch dashboard exported once per day"}, {"k": "C", "t": "A CloudTrail trail for metric datapoints"}, {"k": "D", "t": "A Logs Insights scheduled query against every metric namespace"}], "answer": ["A"], "multi": false, "explanation": "CloudWatch metric streams continuously deliver selected metrics to Amazon Data Firehose and supported partner destinations. Dashboards and CloudTrail do not export metric datapoints, and Logs Insights queries logs rather than metric namespaces."},
{"id": "aa:dop-0141", "sources": ["aa:dop-0141"], "q": "A distributed application emits X-Ray traces. The team needs to search traces for a tenant identifier and error category without creating a separate segment for each value. How should the application record these searchable values?", "options": [{"k": "A", "t": "Add them as indexed X-Ray annotations and query them with filter expressions"}, {"k": "B", "t": "Add them only as unindexed metadata and expect annotation queries to find them"}, {"k": "C", "t": "Store them as CloudFormation stack outputs"}, {"k": "D", "t": "Encode them in the X-Ray sampling percentage"}], "answer": ["A"], "multi": false, "explanation": "X-Ray annotations are indexed key-value fields that can be used in filter expressions. Metadata can hold additional context but is not indexed for trace filtering. Stack outputs and sampling rates do not classify traces."},
{"id": "aa:dop-0142", "sources": ["aa:dop-0142"], "q": "An S3 bucket currently invokes a Lambda function for every object created under logs/. A new SQS-based consumer needs the same events, and the Lambda code must not change. What is the cleanest fanout design?", "options": [{"k": "A", "t": "Send the S3 event notification to an SNS topic and subscribe both the Lambda function and SQS queue"}, {"k": "B", "t": "Create a second overlapping S3 notification with the same prefix and event type"}, {"k": "C", "t": "Send the S3 notification directly to a Kinesis data stream"}, {"k": "D", "t": "Subscribe the SQS queue directly to a CloudWatch Logs log group"}], "answer": ["A"], "multi": false, "explanation": "SNS provides native fanout to Lambda and SQS. Overlapping S3 notification filters for the same event can be rejected as ambiguous, Kinesis Data Streams is not a direct S3 event notification destination, and SQS cannot subscribe directly to a CloudWatch Logs group."},
{"id": "aa:dop-0143", "sources": ["aa:dop-0143"], "q": "GuardDuty is delegated to a central security account for an AWS Organization. High-severity IAM anomaly findings from any member account must invoke custom identity lookup and notification code. Which TWO actions implement this centrally?", "options": [{"k": "A", "t": "Create an EventBridge rule in the delegated GuardDuty administrator account that matches the required findings"}, {"k": "B", "t": "Target a Lambda function that reads the finding account and principal details, performs the lookup, and sends the notifications"}, {"k": "C", "t": "Use Amazon Detective alone to generate and route GuardDuty findings"}, {"k": "D", "t": "Create only an SNS content filter on the nested GuardDuty finding JSON"}, {"k": "E", "t": "Deploy a polling EC2 instance in every member account"}], "answer": ["A", "B"], "multi": true, "explanation": "Applicable member findings are available to EventBridge in the delegated administrator account. A rule can select the finding type or severity and invoke Lambda for arbitrary lookup and notification logic. Detective investigates findings; it does not replace GuardDuty detection and event routing."},
{"id": "aa:dop-0144", "sources": ["aa:dop-0144"], "q": "An EventBridge-based service needs two different recovery controls: retain target delivery failures after retries, and later replay every event from a chosen outage time window through the event bus. Which TWO features meet these separate needs?", "options": [{"k": "A", "t": "Configure an SQS dead-letter queue on the target for exhausted delivery retries"}, {"k": "B", "t": "Create an EventBridge archive and start a replay for the selected time window"}, {"k": "C", "t": "Use the DLQ as an automatic full event-bus history archive"}, {"k": "D", "t": "Use an archive to retry a single target delivery without sending events back to the source bus"}, {"k": "E", "t": "Disable the target retry policy so failed events disappear sooner"}], "answer": ["A", "B"], "multi": true, "explanation": "A target DLQ stores events that EventBridge could not deliver after retries. An archive retains matching bus events and replay sends a selected time range back to the source event bus. The two features solve different failure and historical-reprocessing requirements."},
{"id": "aa:dop-0145", "sources": ["aa:dop-0145"], "q": "A CloudFormation update failed, and rollback is stuck in UPDATE_ROLLBACK_FAILED because a resource was changed outside CloudFormation. After correcting the underlying issue, what should the operator do?", "options": [{"k": "A", "t": "Run ContinueUpdateRollback; specify the minimum ResourcesToSkip only if a failed rollback resource still cannot be restored, then reconcile it before the next update"}, {"k": "B", "t": "Run UpdateStack again while the stack remains in UPDATE_ROLLBACK_FAILED"}, {"k": "C", "t": "Delete the stack immediately, including all production resources"}, {"k": "D", "t": "Mark every resource as skipped without investigating status reasons"}], "answer": ["A"], "multi": false, "explanation": "ContinueUpdateRollback returns the stack toward UPDATE_ROLLBACK_COMPLETE after the cause is fixed. ResourcesToSkip is a last resort for resources that failed during rollback; skipped resources become inconsistent with the template and must be reconciled before another update."},
{"id": "aa:dop-0146", "sources": ["aa:dop-0146"], "q": "An SSM Automation remediation will target 2,000 instances. The team wants a concurrency value of 5% of the fleet and an error-threshold value of 10. Which Automation controls should be set?", "options": [{"k": "A", "t": "Set MaxConcurrency to 5% and MaxErrors to 10"}, {"k": "B", "t": "Set the document timeout to 5% and the retry count to 2,000"}, {"k": "C", "t": "Use a CloudWatch dashboard with no Automation rate controls"}, {"k": "D", "t": "Start 2,000 independent automations simultaneously"}], "answer": ["A"], "multi": false, "explanation": "Automation rate controls use MaxConcurrency to limit parallel target execution and MaxErrors as the failure threshold for stopping new targets. In-flight child automations can make the final failure count exceed the threshold; use MaxConcurrency 1 if a hard maximum is required. Timeouts and dashboards are not rate controls."},
{"id": "aa:dop-0147", "sources": ["aa:dop-0147"], "q": "A deployment role in account B must decrypt artifacts encrypted by a customer-managed KMS key in account A. Which TWO policy changes are required for cross-account KMS access?", "options": [{"k": "A", "t": "Allow the account B role, or account B for delegation, in the KMS key policy in account A"}, {"k": "B", "t": "Attach an IAM policy in account B that allows the role to call the required KMS actions on the key ARN"}, {"k": "C", "t": "Use the AWS managed aws/s3 key because it can be shared across accounts by editing its key policy"}, {"k": "D", "t": "Make the encrypted S3 objects public"}, {"k": "E", "t": "Grant kms:Decrypt only in an SCP, which directly grants permissions"}], "answer": ["A", "B"], "multi": true, "explanation": "Cross-account KMS use requires permission on both sides: the key policy in the owning account must permit the external principal or delegate to its account, and the external role needs an IAM allow. AWS managed key policies cannot be edited for this purpose, and SCPs limit permissions rather than grant them."},
{"id": "aa:dop-0148", "sources": ["aa:dop-0148"], "q": "A company uses an external identity provider and wants automated workforce provisioning plus one centrally managed least-privilege access template assigned across many AWS accounts. Which TWO IAM Identity Center features meet the requirements?", "options": [{"k": "A", "t": "SCIM provisioning from the external identity provider for users and groups"}, {"k": "B", "t": "Permission sets assigned to groups across the required organization accounts"}, {"k": "C", "t": "A shared IAM user and permanent access key in every account"}, {"k": "D", "t": "Root-user federation through S3 bucket policies"}, {"k": "E", "t": "An SCP as the sole mechanism for granting workforce permissions"}], "answer": ["A", "B"], "multi": true, "explanation": "SCIM automates identity and group provisioning into IAM Identity Center. Permission sets are reusable policy templates that Identity Center provisions as controlled roles in assigned accounts. Shared users and root credentials are unsafe; SCPs define permission guardrails but do not grant access."},
{"id": "aa:dop-0149", "sources": ["aa:dop-0149"], "q": "CloudTrail logs must be retained for seven years, protected from deletion even by administrators during the retention period, and verifiable for modification or deletion after delivery. Which TWO controls meet the requirements?", "options": [{"k": "A", "t": "Store the logs in a versioned S3 bucket with Object Lock compliance-mode retention"}, {"k": "B", "t": "Enable CloudTrail log file integrity validation and retain the signed digest files"}, {"k": "C", "t": "Use Object Lock governance mode and give all administrators bypass permission"}, {"k": "D", "t": "Disable S3 versioning after the first log arrives"}, {"k": "E", "t": "Rely on CloudWatch dashboards as immutable evidence"}], "answer": ["A", "B"], "multi": true, "explanation": "Object Lock compliance mode prevents protected object versions from being overwritten or deleted, including by the account root user, until retention expires. CloudTrail digest files provide cryptographic integrity validation. Governance mode can be bypassed by authorized principals."},
{"id": "aa:dop-0150", "sources": ["aa:dop-0150"], "q": "A new AWS customer starting after May 31, 2026 needs organization-wide CloudTrail event retention and SQL analysis. CloudTrail Lake is not available to new customers. Which supported design should the customer use?", "options": [{"k": "A", "t": "Create a multi-Region organization trail to a centralized S3 bucket and query partitioned logs with Amazon Athena"}, {"k": "B", "t": "Create a new CloudTrail Lake event data store despite the new-customer availability restriction"}, {"k": "C", "t": "Use EventBridge without retaining the CloudTrail events"}, {"k": "D", "t": "Rely only on the 90-day per-account Event history for long-term organization analytics"}], "answer": ["A"], "multi": false, "explanation": "For a new customer after the availability cutoff, an organization trail centralizes events from current and future accounts in S3. S3 lifecycle controls retention, and Athena provides SQL analysis. Event history is per-account and limited to 90 days; EventBridge is not a long-term audit store."},
{"id": "aa:dop-0151", "sources": ["aa:dop-0151"], "q": "A company runs a web application on Amazon EC2 instances behind an Application Load Balancer (ALB). The instances run in an Auto Scaling group across multiple Availability Zones. Security policy requires every newly launched instance to register with the company auditing service before it can process transactions. Which solution meets the requirements?", "options": [{"k": "A", "t": "Add a launch lifecycle hook that puts new instances in Pending:Wait. Run a custom registration script, then complete the lifecycle action with CONTINUE on success or ABANDON on failure"}, {"k": "B", "t": "Use an EC2 user data bootstrap script to register the instance and return an error code if registration fails, without a lifecycle hook"}, {"k": "C", "t": "Run a scheduled EventBridge rule every 5 minutes that invokes Lambda to scan the Auto Scaling group and register newly launched instances"}, {"k": "D", "t": "Use an EventBridge rule for EC2 launch events that invokes a Lambda function to register the instance, without a lifecycle hook"}], "answer": ["A"], "multi": false, "explanation": "A launch lifecycle hook pauses the instance in Pending:Wait before it reaches InService and begins receiving ALB traffic. The script calls CompleteLifecycleAction with CONTINUE only after successful audit registration; ABANDON causes Auto Scaling to terminate and replace a failed launch. User data or EventBridge alone can perform registration but does not provide the required lifecycle gate, and scheduled polling also adds delay."},
{"id": "aa:dop-0152", "sources": ["aa:dop-0152"], "q": "A company uses AWS Organizations and operates workloads in three Regions. A baseline SNS notification topic already exists in every member account. The operations team must be alerted when supported service quota usage exceeds 80% in every current and future account, with the least ongoing administration. Which solution meets the requirements?", "options": [{"k": "A", "t": "Use a service-managed CloudFormation StackSet with automatic deployment to create regional CloudWatch alarms in each account. Use the usage metric divided by SERVICE_QUOTA(metric), set the threshold to 80%, and target the local SNS topic"}, {"k": "B", "t": "Enable trusted access for Service Quotas and assume it automatically creates organization-wide usage alarms and notifications"}, {"k": "C", "t": "Run one Trusted Advisor check weekly in the management account and use its status as the exact utilization percentage for every member account"}, {"k": "D", "t": "Create one CloudWatch alarm in the management account without linking source accounts or deploying alarms to member accounts"}], "answer": ["A"], "multi": false, "explanation": "Quota usage metrics and alarms are account- and Region-scoped. A service-managed StackSet can deploy the same alarm resources across organization accounts and Regions and automatically include new accounts. CloudWatch supports the m1/SERVICE_QUOTA(m1)*100 expression and SNS alarm notifications. Service Quotas trusted access supports quota request templates; it does not itself create centralized alarms."},
{"id": "aa:dop-0153", "sources": ["aa:dop-0153"], "q": "Resources in a CloudFormation stack were manually changed after deployment. The company wants CloudFormation to detect changes to optional properties that currently use service defaults and to restore the approved template automatically. Which TWO changes are required?", "options": [{"k": "A", "t": "Explicitly declare the approved values for the tracked properties in the template, including values equal to service defaults"}, {"k": "B", "t": "Use the cloudformation-stack-drift-detection-check AWS Config rule and associate a Systems Manager Automation remediation that updates the stack from the approved template"}, {"k": "C", "t": "Leave optional properties absent because CloudFormation always tracks service defaults that are not in the template"}, {"k": "D", "t": "Use CloudTrail data events as the only source of CloudFormation drift status"}, {"k": "E", "t": "Replace the stack with an AWS Config aggregator, which directly changes resource properties"}], "answer": ["A", "B"], "multi": true, "explanation": "CloudFormation drift detection compares actual values only with properties explicitly represented in the template or parameters, so default-valued properties must be declared. The managed Config rule can initiate drift checks, and Config remediation can invoke Systems Manager Automation to update the stack from the approved template."},
{"id": "aa:dop-0154", "sources": ["aa:dop-0154"], "q": "A serverless application contains API Gateway, Lambda, DynamoDB, and an ElastiCache replication group used for session data. The team wants one infrastructure-as-code deployment with the fewest custom components. What should it do?", "options": [{"k": "A", "t": "Define the serverless resources with AWS SAM resource types and the ElastiCache replication group with its standard CloudFormation resource type in one SAM template"}, {"k": "B", "t": "Use a SAM template only for Lambda and create every other resource through Lambda-backed custom resources"}, {"k": "C", "t": "Deploy ElastiCache manually because SAM templates cannot contain standard CloudFormation resources"}, {"k": "D", "t": "Maintain separate templates because a stack cannot reference both serverless and non-serverless resources"}], "answer": ["A"], "multi": false, "explanation": "A SAM template is an extension of CloudFormation and its Resources section can contain a combination of AWS::Serverless resources and standard CloudFormation resources. Therefore one template can use SAM shorthand for the API and functions while declaring DynamoDB and ElastiCache resources directly."},
{"id": "aa:dop-0155", "sources": ["aa:dop-0155"], "q": "An operations team needs an email alert whenever an Amazon ECS task stops because an essential container exits. An SNS topic and email subscription already exist. Which solution requires the least development effort?", "options": [{"k": "A", "t": "Create an EventBridge rule for ECS Task State Change events with lastStatus STOPPED and stoppedReason \"Essential container in task exited\"; set the SNS topic as the target"}, {"k": "B", "t": "Poll DescribeTasks from a scheduled Lambda function and publish matching results to SNS"}, {"k": "C", "t": "Add an SNS destination property to each essential container in the ECS task definition"}, {"k": "D", "t": "Configure the ECS cluster to send all container stdout directly to the email endpoint"}], "answer": ["A"], "multi": false, "explanation": "ECS emits task state change events to EventBridge. A rule can match STOPPED tasks with the exact essential-container stopped reason and publish directly to SNS, eliminating polling code. ECS task definitions do not provide a direct SNS notification property."},
{"id": "aa:dop-0156", "sources": ["aa:dop-0156"], "q": "Developers can launch EC2 instances directly, but security policy permits only a Region-specific list of hardened AMIs. The company must discover and terminate running instances that use any other AMI. Which solution is the most operationally efficient?", "options": [{"k": "A", "t": "Deploy the approved-amis-by-id AWS Config managed rule with the approved IDs and configure automatic remediation through the AWS-TerminateEC2Instance Systems Manager Automation runbook"}, {"k": "B", "t": "Publish approved AMIs in Service Catalog but continue allowing unrestricted direct RunInstances calls"}, {"k": "C", "t": "Attach an SCP to an IAM group and use it to terminate existing noncompliant instances"}, {"k": "D", "t": "Send a weekly inventory email and ask each developer to terminate noncompliant instances manually"}], "answer": ["A"], "multi": false, "explanation": "The approved-amis-by-id managed rule marks running EC2 instances that use other AMIs as NON_COMPLIANT. AWS Config automatic remediation invokes Systems Manager Automation, and AWS-TerminateEC2Instance performs the required termination. Service Catalog alone does not detect bypasses, SCPs attach to organization entities rather than IAM groups, and SCPs do not remediate existing resources."},
{"id": "aa:dop-0157", "sources": ["aa:dop-0157"], "q": "Applications and console users upload documents to an S3 bucket. A web application marks documents that must be retained by setting the object tag Retain=true. All other documents must expire after 90 days, including uploads that arrive without tags. Which TWO actions meet the requirements?", "options": [{"k": "A", "t": "Invoke a Lambda function from S3 ObjectCreated events to add Retain=false when the Retain tag is absent"}, {"k": "B", "t": "Create an S3 Lifecycle expiration rule for objects tagged Retain=false with an age of 90 days"}, {"k": "C", "t": "Create an unfiltered 90-day expiration rule for the entire bucket"}, {"k": "D", "t": "Deny DeleteObject when Retain=true and expect that policy condition alone to select lifecycle candidates"}, {"k": "E", "t": "Use an S3 Inventory report once per year as the deletion mechanism"}], "answer": ["A", "B"], "multi": true, "explanation": "The creation event handles upload clients that omit tags by assigning an explicit non-retained state. An S3 Lifecycle rule can filter on an object tag and expire only Retain=false objects after 90 days. An unfiltered rule would include retained documents, and a bucket-policy deny is not a lifecycle selector."},
{"id": "aa:dop-0158", "sources": ["aa:dop-0158"], "q": "An organization requires continuous detection and automatic correction of public-read or public-write access granted through S3 bucket policies, bucket ACLs, or Block Public Access settings in all accounts and Regions. New accounts must inherit the controls. Which solution best meets the requirement?", "options": [{"k": "A", "t": "In every required Region, deploy an organization AWS Config conformance pack containing the S3 public-access managed rules and Systems Manager Automation remediations that configure Block Public Access or remove public grants"}, {"k": "B", "t": "Create an organization CloudTrail trail and expect EventBridge in one security account to consume API events from the trail S3 bucket automatically"}, {"k": "C", "t": "Enable S3 data events on each bucket and use them to detect every future bucket-policy change across accounts"}, {"k": "D", "t": "Create EventBridge global endpoints because they replicate all events between accounts and Regions"}], "answer": ["A"], "multi": false, "explanation": "An organization conformance pack deploys Config rules and remediation actions across AWS Organizations and is deployed in each required Region. The S3 public-access rules evaluate bucket policies, bucket ACLs, and Block Public Access settings; Systems Manager Automation can correct noncompliant buckets. Trail files do not automatically become cross-account EventBridge events, S3 data events are object operations, and global endpoints provide Regional failover rather than organization event replication."},
{"id": "aa:dop-0159", "sources": ["aa:dop-0159"], "q": "A REST API currently sends {\"text\":\"...\"} to a Lambda function. A new Lambda release requires both text and locale, but existing clients cannot all migrate immediately. The company wants only one production Lambda implementation while offering a new API contract. Which deployment approach meets the requirements?", "options": [{"k": "A", "t": "Deploy the new Lambda version, point both API versions to it, and add an integration request mapping template to the legacy API that supplies a default locale; let the new API pass the client locale"}, {"k": "B", "t": "Keep the old Lambda function for the legacy API and deploy a separate production function for the new API indefinitely"}, {"k": "C", "t": "Point the legacy API directly to the new function without transforming requests and require all clients to change immediately"}, {"k": "D", "t": "Add the default locale mapping only to the new API while leaving the old API connected to the old function"}], "answer": ["A"], "multi": false, "explanation": "API Gateway integration request mapping templates can transform the legacy request into the new backend schema. Both API contracts can therefore invoke the same production Lambda implementation, while old clients receive a defined default and new clients choose a locale."},
{"id": "aa:dop-0160", "sources": ["aa:dop-0160"], "q": "A company uses CodeDeploy for EC2 instances and a large fleet of on-premises Linux servers. The on-premises servers must avoid long-lived AWS access keys and be selected for deployments by environment. Which approach is the most secure?", "options": [{"k": "A", "t": "Create a least-privilege IAM role, distribute periodically refreshed STS session credentials through the company identity system, register each server with an IAM session ARN, install the CodeDeploy agent, and target deployment groups with on-premises instance tags"}, {"k": "B", "t": "Create one IAM user with a permanent access key, copy the key to every server, and list server IDs directly in the deployment group"}, {"k": "C", "t": "Store the root user access key on the deployment server and rotate it once per year"}, {"k": "D", "t": "Install only the CodeDeploy agent; unregistered on-premises servers are discovered automatically from their IP addresses"}], "answer": ["A"], "multi": false, "explanation": "CodeDeploy supports on-premises registration with an IAM session ARN and periodically refreshed temporary STS credentials; AWS recommends this over static IAM-user credentials for production fleets. Registered on-premises instances are tagged, and deployment groups use tag groups to select them."},
{"id": "aa:dop-0161", "sources": ["aa:dop-0161"], "q": "A stateless EC2 web tier uses an RDS for MySQL Multi-AZ DB instance. A disaster recovery Region must achieve an RTO below 2 hours and an RPO below 10 minutes. Full duplicate compute capacity is not required during normal operation. Which design is the most cost-effective?", "options": [{"k": "A", "t": "Maintain current AMIs and a tested CloudFormation template in the DR Region, continuously replicate to a cross-Region RDS read replica, and on failover create the web stack, promote the replica, and change DNS"}, {"k": "B", "t": "Copy EBS and RDS snapshots to the DR Region once every hour and rebuild all infrastructure manually"}, {"k": "C", "t": "Run a fully scaled active-active web tier and Aurora global database in both Regions regardless of the cost requirement"}, {"k": "D", "t": "Keep no resources or data in the DR Region and restore only from the most recent local backup after a regional outage"}], "answer": ["A"], "multi": false, "explanation": "A pilot-light design keeps the stateful data continuously replicated while deferring most compute cost. RDS cross-Region read replicas use asynchronous replication and can be promoted during recovery; tested CloudFormation and replicated AMIs allow the stateless tier to be created within the RTO. Hourly copies cannot meet the RPO, while active-active is more expensive than required."},
{"id": "aa:dop-0162", "sources": ["aa:dop-0162"], "q": "An Auto Scaling group contains EC2 instances that have diverged because of in-place patches and manual changes. The company wants every launch to use the same approved image and wants controlled replacement of the existing fleet whenever the application or operating system changes. Which solution is best?", "options": [{"k": "A", "t": "Bake a new immutable AMI, create a new launch template version, update the Auto Scaling group, and start an Instance Refresh with health checks and suitable minimum healthy capacity; use Systems Manager for controlled fleet-wide operations"}, {"k": "B", "t": "Patch packages from internet repositories in user data on every launch and keep existing instances indefinitely"}, {"k": "C", "t": "Use the NewestInstance termination policy so older configurations remain in service"}, {"k": "D", "t": "Use AWS Config to install emergency patches directly on each instance without Systems Manager or replacement"}], "answer": ["A"], "multi": false, "explanation": "A versioned launch template tied to a baked AMI makes new launches deterministic. Instance Refresh replaces existing instances from the desired launch template version while honoring health and availability settings. Systems Manager provides auditable fleet operations; Config evaluates configuration but is not a patch execution service."},
{"id": "aa:dop-0163", "sources": ["aa:dop-0163"], "q": "EC2 workers in an Auto Scaling group process an SQS queue. CPU utilization remains low even when the queue grows, and a message must normally wait no more than 60 seconds. Each instance processes one message in an average of 0.5 seconds. Which scaling design is the most reliable and operationally efficient?", "options": [{"k": "A", "t": "Use target tracking on a metric-math expression that divides visible queue messages by InService instances, with an acceptable backlog target of 120 messages per instance"}, {"k": "B", "t": "Use target tracking on NumberOfMessagesReceived because it represents the unprocessed backlog"}, {"k": "C", "t": "Lower the CPU target until scaling happens, even though CPU is not proportional to queue delay"}, {"k": "D", "t": "Place an Application Load Balancer in front of SQS and scale on ALBRequestCountPerTarget"}], "answer": ["A"], "multi": false, "explanation": "Backlog per instance is visible messages divided by InService capacity and is proportional to the work each instance must drain. The acceptable target is maximum latency divided by average processing time: 60/0.5 = 120. AWS now supports metric math for this target, avoiding a custom metric publisher. NumberOfMessagesReceived is throughput, not current backlog."},
{"id": "aa:dop-0164", "sources": ["aa:dop-0164"], "q": "A closed-source application writes one JSON record per line to local EC2 log files. Records with eventType=\"diagnostic\" contain no PII, while eventType=\"customer\" records contain addresses and phone numbers. An external support team needs near-real-time diagnostic records without SSH access. Which solution is the most cost-effective?", "options": [{"k": "A", "t": "Use the CloudWatch agent to send the files to CloudWatch Logs, apply a JSON subscription filter for diagnostic records, invoke Lambda to write matches to S3, and grant the support team read access to that bucket"}, {"k": "B", "t": "Give the support team SSH access and rely on a written instruction not to open customer records"}, {"k": "C", "t": "Run a continuously provisioned OpenSearch cluster and ingest all records, including PII, for occasional support investigations"}, {"k": "D", "t": "Configure the unified CloudWatch agent to deliver local log files directly to an S3 bucket without CloudWatch Logs or another delivery service"}], "answer": ["A"], "multi": false, "explanation": "The CloudWatch agent can collect local files into CloudWatch Logs. A JSON subscription filter forwards only matching diagnostic records to Lambda in near real time, and Lambda can store the sanitized stream in S3 for low-cost controlled access. The design excludes the PII-bearing record type and avoids production SSH or an always-on search cluster."},
{"id": "aa:dop-0165", "sources": ["aa:dop-0165"], "q": "Separate CodePipeline pipelines currently rebuild the same commit for development and UAT, and the resulting applications sometimes differ. The environments must also remain structurally identical. Which redesign provides the strongest guarantee?", "options": [{"k": "A", "t": "Use one pipeline to build once, pass that immutable output artifact to both deployment stages, and provision both environments from the same parameterized CloudFormation template"}, {"k": "B", "t": "Keep two independent builds but use buildspec files that are intended to be equivalent"}, {"k": "C", "t": "Build separately and compare source commit IDs, without comparing or reusing the produced artifacts"}, {"k": "D", "t": "Reuse an EC2 instance for both environments and configure each environment manually after deployment"}], "answer": ["A"], "multi": false, "explanation": "A CodePipeline output artifact can be consumed by more than one later action or stage. Building once removes nondeterminism between rebuilds, and deploying the same artifact ensures binary identity. A shared parameterized CloudFormation template controls environment structure; independent builds and manual configuration do not provide those guarantees."},
{"id": "aa:dop-0166", "sources": ["aa:dop-0166"], "q": "An AWS SAM application uses an API Gateway HTTP API. Each request contains a proprietary token and tenant header that must be validated by an existing authentication service. The service does not issue JWTs and is not compatible with OpenID Connect or SAML. Which authentication mechanism should the template configure?", "options": [{"k": "A", "t": "A Lambda REQUEST authorizer for AWS::Serverless::HttpApi with the token and tenant headers as identity sources"}, {"k": "B", "t": "A native JWT authorizer with a fabricated issuer URL for the proprietary service"}, {"k": "C", "t": "An API key only, because API keys authenticate and authorize arbitrary proprietary tokens"}, {"k": "D", "t": "An S3 bucket policy that calls the authentication service before API Gateway invokes Lambda"}], "answer": ["A"], "multi": false, "explanation": "HTTP APIs support Lambda request authorizers, and SAM can define the authorizer and header identity sources. The authorizer function can call the proprietary authentication service and return an authorization result. A JWT authorizer requires a compatible JWT issuer, and API keys are intended for usage identification and throttling rather than custom authentication."},
{"id": "aa:dop-0167", "sources": ["aa:dop-0167"], "q": "An Elastic Beanstalk environment was created with the EB CLI. A later application bundle sets InstanceType in .ebextensions, but deployments continue using the instance type chosen during environment creation. Other new settings in the file take effect. What is the cause?", "options": [{"k": "A", "t": "The EB CLI applies a recommended instance-type value directly to the environment at the API level, which has higher precedence than saved configurations, .ebextensions, and defaults"}, {"k": "B", "t": ".ebextensions can set environment variables but can never set an EC2 instance type"}, {"k": "C", "t": "Default values always override values in .ebextensions"}, {"k": "D", "t": "Elastic Beanstalk silently ignores all .ebextensions files when the EB CLI created the environment"}], "answer": ["A"], "multi": false, "explanation": "Elastic Beanstalk precedence is direct environment/API settings, saved configurations, .ebextensions, then defaults. The EB CLI and console set recommended values such as InstanceType at the highest environment/API level, so a lower-precedence configuration file cannot replace that setting until the higher-level value is changed or removed."},
{"id": "aa:dop-0168", "sources": ["aa:dop-0168"], "q": "A CodeDeploy blue/green deployment to an EC2 Auto Scaling group must roll back automatically when application logs show too many ERROR records. The application does not return these failures as ALB HTTP error codes. Which TWO actions meet the requirement?", "options": [{"k": "A", "t": "Send the application logs to CloudWatch Logs and create a metric filter plus a CloudWatch alarm for the unacceptable error rate"}, {"k": "B", "t": "Associate the alarm with the CodeDeploy deployment group and enable automatic rollback when the alarm threshold is met"}, {"k": "C", "t": "Alarm only on ALB HTTPCode_Target_4XX_Count even though the failures appear only in application logs"}, {"k": "D", "t": "Publish an SNS message and configure CodeDeploy to poll the topic for rollback commands"}, {"k": "E", "t": "Run an hourly Lambda poll that calls rollback regardless of CodeDeploy alarm integration"}], "answer": ["A", "B"], "multi": true, "explanation": "A CloudWatch Logs metric filter converts matching application error records into a metric that an alarm can evaluate. CodeDeploy deployment groups can monitor CloudWatch alarms and automatically deploy the last known good revision when an associated alarm activates. ALB metrics do not observe log-only errors, and CodeDeploy does not consume SNS messages as rollback commands."},
];
